window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[226]={"id":"226","numero":226,"titre":"Maladie thrombo-embolique veineuse — TVP & EP","objectifs":[{"id":"226-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une thrombose veineuse profonde (TVP), d’une TVP proximale, d’une TVP distale, d’une embolie pulmonaire (EP), d’une EP à haut risque","contenu":"<p>La <span class=\"kw-def\">maladie thrombo-embolique veineuse (MTEV)</span> est une entité unique dont les <strong>deux manifestations cliniques</strong> sont la <span class=\"kw-def\">TVP</span> (≈ 2/3 des cas) et l'<span class=\"kw-def\">EP</span> (≈ 1/3). C'est le symptôme qui guide la définition de chacune.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">TVP</span></td><td>Obstruction <span class=\"kw-def\">thrombotique</span> d'un tronc veineux <strong>profond</strong>, localisée le plus souvent aux <span class=\"kw-clinique\">membres inférieurs</span></td></tr>\n          <tr><td><span class=\"kw-def\">TVP proximale</span></td><td>Thrombose <strong>sus-poplitée</strong> : veines poplitée, fémorale, iliaque, cave — <span class=\"kw-alerte\">risque d'EP élevé</span></td></tr>\n          <tr><td><span class=\"kw-def\">TVP distale</span></td><td>Thrombose <strong>sous-poplitée</strong> : veines jambières (tibiale antérieure et postérieure, fibulaire) et surales (soléaire, gastrocnémienne)</td></tr>\n          <tr><td><span class=\"kw-def\">EP</span></td><td>Obstruction des <span class=\"kw-def\">artères pulmonaires</span> ou de leurs branches par des <span class=\"kw-etio\">thrombus</span></td></tr>\n          <tr><td><span class=\"kw-def\">EP à haut risque</span></td><td>EP définie par la présence d'un <span class=\"kw-alerte\">état de choc</span> — forme rare (≈ <span class=\"kw-chiffre\">5 %</span>) mais <span class=\"kw-alerte\">mortalité 25-50 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Épidémiologie</span>.</strong> <span class=\"kw-def\">Incidence</span> de la MTEV <span class=\"kw-chiffre\">1-2/1000/an</span>, en augmentation avec l'âge (<span class=\"kw-chiffre\">1/100</span> après <span class=\"kw-chiffre\">75 ans</span> contre <span class=\"kw-chiffre\">1/10 000</span> avant <span class=\"kw-chiffre\">40 ans</span>). Maladie grave : <span class=\"kw-alerte\">mortalité à 3 mois 5-10 %</span> ; chaque année <span class=\"kw-chiffre\">35 000</span> patients sont hospitalisés en France pour une EP, avec une <span class=\"kw-alerte\">mortalité hospitalière de 5 %</span>.</p>\n      <div class=\"callout callout-danger\"><strong>EP à haut risque.</strong> Le critère définissant n'est pas la taille du <span class=\"kw-etio\">thrombus</span> mais le <span class=\"kw-alerte\">retentissement hémodynamique</span> : peu importe le reste, une <span class=\"kw-chiffre\">PAS &lt; 90 mmHg</span> classe l'EP en <strong>haut risque</strong>.</div>","frequence":0},{"id":"226-2","rang":"A","rubrique":"Étiologies","titre":"Connaître les situations qui favorisent la maladie thromboembolique veineuse (MTEV) : circonstances de survenue, facteurs favorisants temporaires et persistants","contenu":"<p>La MTEV est une <span class=\"kw-def\">maladie multifactorielle</span>. Les facteurs favorisants se croisent selon deux axes : <strong>transitoire <span class=\"kw-bio\">vs</span> persistant</strong> et <strong>majeur <span class=\"kw-bio\">vs</span> mineur</strong>. Cette <span class=\"kw-def\">classification</span> commande la durée du traitement <span class=\"kw-ttt\">anticoagulant</span>.</p>\n      <table >\n        <thead><tr><th></th><th>Majeurs</th><th>Mineurs</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Transitoires</strong></td>\n            <td>\n              <span class=\"kw-etio\">Chirurgie sous anesthésie générale</span> &lt;<span class=\"kw-chiffre\"> 3 mois</span> ; <span class=\"kw-etio\">fracture d'un membre inférieur</span> &lt;<span class=\"kw-chiffre\"> 3 mois</span> ; <span class=\"kw-etio\">immobilisation &gt; 3 jours</span> pour motif médical aigu &lt;<span class=\"kw-chiffre\"> 3 mois</span> ; <span class=\"kw-etio\">COP, grossesse, post-partum, THM</span> &lt;<span class=\"kw-chiffre\"> 3 mois</span>\n            </td>\n            <td>\n              <span class=\"kw-etio\">Traumatisme d'un MI non plâtré</span> avec mobilité réduite <span class=\"kw-chiffre\">≥ 3 jours</span> &lt;<span class=\"kw-chiffre\"> 2 mois</span> ; <span class=\"kw-etio\">immobilisation &lt; 3 jours</span> &lt;<span class=\"kw-chiffre\"> 3 mois</span> ; <span class=\"kw-etio\">voyage &gt; 6 h</span> ; traitement par <span class=\"kw-ttt\">EPO</span> ; <span class=\"kw-etio\">voie veineuse centrale</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Persistants</strong></td>\n            <td>\n              <span class=\"kw-etio\">Cancer actif</span> ; thrombophilie majeure : déficit en <span class=\"kw-bio\">antithrombine</span>, <span class=\"kw-bio\">SAPL</span> <em>(seule thrombophilie <span class=\"kw-etio\">acquise</span>)</em>\n            </td>\n            <td>\n              <span class=\"kw-chiffre\">Âge &gt; 65 ans</span> ; <span class=\"kw-etio\">obésité</span>, <span class=\"kw-def\">syndrome néphrotique</span>, HPN ; <span class=\"kw-etio\">MICI</span>, maladies inflammatoires chroniques articulaires ; thrombophilie non majeure : déficit en <span class=\"kw-bio\">protéine C / protéine S</span>, mutation <span class=\"kw-bio\">Leiden du facteur V</span>, mutation <span class=\"kw-bio\">G20210A de la prothrombine</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Pièges classiques.</strong> Le <span class=\"kw-alerte\">tabac</span> et la <span class=\"kw-alerte\">dyslipidémie</span> ne sont <strong>pas</strong> des <span class=\"kw-def\">facteurs de risque</span> de MTEV (à la différence du risque artériel). Dans <span class=\"kw-chiffre\">50 %</span> des cas <strong>aucun facteur</strong> n'est identifié. Un <span class=\"kw-etio\">ATCD familial de MTEV</span>, même sans thrombophilie <span class=\"kw-etio\">héréditaire</span> détectée, est considéré comme un marqueur de thrombophilie héréditaire.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 222 — FDR cardiovasculaire</em></p>","frequence":6},{"id":"226-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie de la MTEV y compris les formes familiales","contenu":"<p>La constitution du <span class=\"kw-etio\">thrombus</span> repose sur la <span class=\"kw-def\">triade de Virchow</span> : <strong><span class=\"kw-def\">stase veineuse</span></strong> + <strong><span class=\"kw-def\">lésion pariétale</span></strong> + <strong><span class=\"kw-def\">anomalies de l'hémostase</span></strong> (hypercoagulabilité). Le point de départ est souvent <strong>distal</strong>, dans les zones de ralentissement du flux (veines soléaires, valvules, abouchement des collatérales).</p>\n      <p><strong>Lien <span class=\"kw-def\">TVP</span> → EP.</strong> La plupart des thrombi fibrino-cruoriques proviennent des veines profondes des MI et du pelvis : l'<span class=\"kw-def\">EP est secondaire à une TVP dans 70 %</span> des cas, survenant <span class=\"kw-chiffre\">3 à 7 jours</span> après. Environ <span class=\"kw-chiffre\">50 %</span> des patients porteurs d'une <span class=\"kw-def\">TVP</span> proximale ont une EP, y compris asymptomatique.</p>\n      <table >\n        <thead><tr><th>Conséquence</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Hémodynamique de l'EP</strong></td><td>Obstruction artérielle → ↑ résistances pulmonaires (au-delà de <span class=\"kw-chiffre\">30-50 %</span> d'obstruction) → <span class=\"kw-def\">HTAP pré-capillaire</span> → ↑ post-charge du VD → <span class=\"kw-alerte\">dilatation du VD</span> → septum paradoxal comprimant le VG → ↓ précharge VG → ↓ débit cardiaque → ↓ PA. L'ischémie du VD aboutit au <span class=\"kw-alerte\">cœur pulmonaire aigu</span></td></tr>\n          <tr><td><strong>Hypoxémie</strong></td><td>D'abord <span class=\"kw-def\">effet espace mort</span> (alvéoles ventilées non perfusées), puis <span class=\"kw-def\">effet shunt</span> — mécanisme principal — par bronchoconstriction et redistribution du flux ; l'hyperventilation réactionnelle donne une <span class=\"kw-bio\">hypocapnie</span> et une <span class=\"kw-bio\">alcalose respiratoire</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Formes familiales.</strong> Les <span class=\"kw-def\">thrombophilies héréditaires</span> sont retrouvées chez environ 1/4 des patients, mais leur impact clinique est faible — sauf le déficit en antithrombine.</p>\n      <ul>\n        <li><span class=\"kw-bio\">Déficit en antithrombine</span> — facteur <span class=\"kw-etio\">héréditaire</span> le <strong>plus thrombogène</strong>, même à l'état hétérozygote, mais le plus rare.</li>\n        <li><span class=\"kw-bio\">Déficit en protéine C</span> et <span class=\"kw-bio\">protéine S</span> — thrombophilies non majeures.</li>\n        <li>Mutation <span class=\"kw-bio\">Leiden du facteur V</span> et mutation <span class=\"kw-bio\">G20210A de la prothrombine</span> (hétéro- ou homozygote) — non majeures.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 194 — <span class=\"kw-def\">Lupus</span> - SAPL</em></p>","frequence":3},{"id":"226-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une MTEV (TVP, EP) : signes cliniques, stratégie diagnostique incluant les scores, signes paracliniques, principaux diagnostics différentiels","contenu":"<p>La <strong>clinique ne permet <span class=\"kw-ci\">jamais de</span> poser le diagnostic</strong> de MTEV : elle n'a qu'une valeur d'orientation. Le diagnostic combine toujours une <span class=\"kw-def\">probabilité clinique</span> (<span class=\"kw-def\">score</span>) et un examen paraclinique objectif. Aucun examen isolé ne confirme ou n'exclut à lui seul.</p>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-def\">TVP</span></th><th>EP</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Signes cliniques</strong></td>\n            <td><span class=\"kw-clinique\">Douleur du mollet</span> (≈<span class=\"kw-chiffre\"> 60 %</span>) ; <span class=\"kw-clinique\">œdème unilatéral</span> prenant le godet (&gt; <span class=\"kw-chiffre\">3 cm</span> <span class=\"kw-bio\">vs</span> côté controlatéral) ; signe de <span class=\"kw-clinique\">Homans</span> ; ↓ ballottement du mollet ; signes inflammatoires locaux ; survenue <strong>brutale et unilatérale</strong></td>\n            <td><span class=\"kw-clinique\">Dyspnée brutale</span> ; <span class=\"kw-clinique\">douleur thoracique pleurale</span> ; <span class=\"kw-clinique\">hémoptysie</span> ; <span class=\"kw-clinique\">syncope</span> ; <span class=\"kw-clinique\">tachypnée</span> constante ; signes d'<span class=\"kw-def\">insuffisance cardiaque</span> droite aiguë (TJ, RHJ)</td></tr>\n          <tr><td><strong>Forme grave</strong></td>\n            <td><span class=\"kw-alerte\">Phlegmatia alba dolens</span> : douleur violente, impotence absolue, <span class=\"kw-clinique\">fièvre</span>, jambe livide, <span class=\"kw-clinique\">œdème</span> dur ne prenant pas le godet</td>\n            <td><span class=\"kw-alerte\">EP à haut risque</span> : <span class=\"kw-alerte\">état de choc</span> (voir rubrique <span class=\"kw-alerte\">Urgence</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Une <span class=\"kw-clinique\">dyspnée brutale</span> avec une <strong>auscultation pulmonaire normale</strong> est une <span class=\"kw-alerte\">EP jusqu'à preuve du contraire</span>. De même, une <span class=\"kw-clinique\">dyspnée</span> ou une <span class=\"kw-clinique\">douleur thoracique</span> aiguë chez un patient porteur d'une <span class=\"kw-def\">TVP</span> fait conclure à une EP.</div>\n      <p><strong>Scores de probabilité clinique.</strong> <span class=\"kw-def\">Score</span> de <span class=\"kw-def\">Wells</span> pour la <span class=\"kw-def\">TVP</span> ; scores de <span class=\"kw-def\">Wells</span> ou de <span class=\"kw-def\">Genève révisé</span> pour l'EP.</p>\n      <table >\n        <thead><tr><th>Score de Wells — <span class=\"kw-def\">TVP</span></th><th>Points</th></tr></thead>\n        <tbody>\n          <tr><td>Parésie / paralysie / immobilisation plâtrée d'un MI</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Chirurgie</span> récente (&lt; 4 sem.) ou alitement (&gt; 3 j)</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td>Cancer évolutif connu</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td>ATCD de <span class=\"kw-def\">TVP</span> ou d'EP</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td>Sensibilité le long du trajet veineux profond</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Œdème</span> généralisé du MI / <span class=\"kw-clinique\">œdème</span> du mollet &gt;<span class=\"kw-chiffre\"> 3 cm</span> / <span class=\"kw-clinique\">œdème</span> prenant le godet</td><td><span class=\"kw-chiffre\">1</span> chacun</td></tr>\n          <tr><td>Circulation collatérale superficielle non variqueuse</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-def\">Diagnostic différentiel</span> au moins aussi probable</td><td><span class=\"kw-chiffre\">−2</span></td></tr>\n          <tr><td><strong>Interprétation</strong></td><td>Faible (improbable) : <span class=\"kw-chiffre\">&lt; 2</span> &nbsp;—&nbsp; Forte (probable) : <span class=\"kw-chiffre\">≥ 2</span></td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Score</span> de Genève révisé — EP</th><th>Points</th></tr></thead>\n        <tbody>\n          <tr><td>Âge &gt;<span class=\"kw-chiffre\"> 65 ans</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td>ATCD de <span class=\"kw-def\">TVP</span> ou d'EP</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Chirurgie</span> ou fracture dans le mois</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td>Néoplasie active</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Hémoptysie</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Douleur unilatérale</span> du MI</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td>Pouls <span class=\"kw-chiffre\">75-94 bpm</span> / <span class=\"kw-chiffre\">≥ 95 bpm</span></td><td><span class=\"kw-chiffre\">1</span> / <span class=\"kw-chiffre\">2</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Douleur à la palpation</span> du trajet veineux du MI <em>et</em> <span class=\"kw-clinique\">œdème unilatéral</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><strong>Interprétation (3 niveaux)</strong></td><td>Faible (&lt;<span class=\"kw-chiffre\"> 10 %</span>) : <span class=\"kw-chiffre\">0-1</span> &nbsp;—&nbsp; Intermédiaire (<span class=\"kw-chiffre\">30-40 %</span>) : <span class=\"kw-chiffre\">2-4</span> &nbsp;—&nbsp; Forte (&gt;<span class=\"kw-chiffre\"> 60 %</span>) : <span class=\"kw-chiffre\">≥ 5</span></td></tr>\n          <tr><td><strong>Interprétation (2 niveaux)</strong></td><td>Peu probable : <span class=\"kw-chiffre\">0-2</span> &nbsp;—&nbsp; Probable : <span class=\"kw-chiffre\">≥ 3</span></td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Score</span> de Wells — EP</th><th>Points</th></tr></thead>\n        <tbody>\n          <tr><td>ATCD de <span class=\"kw-def\">TVP</span> ou d'EP</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Chirurgie</span> récente ou immobilisation &lt;<span class=\"kw-chiffre\"> 4 semaines</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td>Cancer actif</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Hémoptysie</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td>FC &gt;<span class=\"kw-chiffre\"> 100 bpm</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td>Signes cliniques de <span class=\"kw-def\">TVP</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-def\">Diagnostic différentiel</span> peu probable</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><strong>Interprétation</strong></td><td>Peu probable : <span class=\"kw-chiffre\">0-1</span> &nbsp;—&nbsp; Probable : <span class=\"kw-chiffre\">≥ 2</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Signes paracliniques d'orientation dans l'EP</strong> (ni sensibles ni spécifiques) :</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Anomalies</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">ECG</span> — mémo <strong>BASTON</strong></td><td><strong>B</strong>loc de branche droit ; <strong>A</strong>xe dévié à droite ; <strong>S</strong>1Q3 ; <strong>T</strong>achycardie sinusale (le plus fréquent) ; <strong>O</strong>ndes T négatives de V1 à V4 ; <strong>N</strong>ormal possible</td></tr>\n          <tr><td><span class=\"kw-imagerie\">RXT</span> — mémo <strong>ABCDEF</strong></td><td><strong>A</strong>scension d'une coupole ; <strong>B</strong>ande d'atélectasie ; <strong>C</strong>larté d'un champ pulmonaire ; <strong>D</strong>ilatation des cavités droites ; <strong>É</strong>panchement pleural ; in<strong>F</strong>arctus pulmonaire — <span class=\"kw-imagerie\">RXT</span> souvent <strong>normale</strong></td></tr>\n          <tr><td><span class=\"kw-bio\">Gazométrie</span></td><td>Non systématique : soit normale (≈<span class=\"kw-chiffre\"> 20 %</span>), soit <span class=\"kw-def\">effet shunt</span> — hypoxémie + hypocapnie (PaO₂ + PaCO₂ &lt; <span class=\"kw-chiffre\">120 mmHg</span>)</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/226/ecg-baston-s1q3.jpg\" alt=\"ECG montrant des signes de cœur pulmonaire aigu au cours d'une embolie pulmonaire — aspect S1Q3 et tachycardie sinusale\" loading=\"lazy\">\n        <figcaption><span class=\"kw-bio\">ECG</span> : signes de cœur pulmonaire aigu — aspect <strong>S1Q3</strong> (onde S en D1, onde Q en D3) et <span class=\"kw-clinique\">tachycardie</span> sinusale. Ces signes sont inconstants et aspécifiques. Source : fiche source EDN item 226.</figcaption>\n      </figure>\n      <p><strong>Stratégie diagnostique.</strong> Le diagnostic d'EP doit être établi en moins de <span class=\"kw-chiffre\">24 h</span>. Démarche commune :</p>\n      <ol>\n        <li>Suspicion clinique → calcul de la <span class=\"kw-def\">probabilité clinique</span> (<span class=\"kw-def\">score</span>).</li>\n        <li>Probabilité <strong>non forte</strong> → dosage des <span class=\"kw-bio\">D-dimères</span> ; s'ils sont négatifs, le diagnostic est éliminé.</li>\n        <li>Probabilité <strong>forte</strong> ou <span class=\"kw-bio\">D-dimères</span> positifs → <span class=\"kw-imagerie\">imagerie d'emblée</span> (<span class=\"kw-imagerie\">échodoppler</span> veineux pour la <span class=\"kw-def\">TVP</span>, <span class=\"kw-imagerie\">angio-<span class=\"kw-imagerie\">TDM</span></span> pour l'EP).</li>\n      </ol>","frequence":9},{"id":"226-5","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir identifier et connaître la démarche diagnostique en cas d’EP à haut risque","contenu":"<p>L'<span class=\"kw-def\">EP à haut risque</span> est une forme rare (≈ <span class=\"kw-chiffre\">5 %</span> des EP) mais de <span class=\"kw-def\">pronostic</span> redoutable : <span class=\"kw-alerte\">mortalité 25-50 %</span>. Elle se définit par la présence d'un <span class=\"kw-alerte\">état de choc</span> — peu importe les autres paramètres, une <span class=\"kw-chiffre\">PAS &lt; 90 mmHg</span> (ou une chute &gt;<span class=\"kw-chiffre\"> 40 mmHg</span> pendant <span class=\"kw-chiffre\">≥ 15 min</span>) suffit à la classer en haut risque.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> vitale.</strong> Devant un patient en <span class=\"kw-alerte\">choc</span> avec suspicion d'EP, la démarche diagnostique est adaptée à l'instabilité hémodynamique : on ne transporte pas un patient instable au <span class=\"kw-imagerie\">scanner</span>.</div>\n      <p><strong>Démarche diagnostique en cas d'instabilité :</strong></p>\n      <ol>\n        <li>Réaliser une <span class=\"kw-imagerie\">échographie cardiaque trans-thoracique (ETT)</span> au lit du patient : la probabilité clinique est ici toujours forte. La recherche de <span class=\"kw-alerte\">dilatation et de dysfonction du VD</span> (signes indirects) suffit à orienter et à débuter le traitement.</li>\n        <li>L'<span class=\"kw-imagerie\">angio-TDM thoracique</span> confirme le diagnostic dès que le patient est <strong>transportable / stabilisé</strong>.</li>\n        <li>L'absence de signe de surcharge des cavités droites en <span class=\"kw-imagerie\">ETT</span> rend le diagnostic d'EP grave peu probable et fait rechercher une autre cause de <span class=\"kw-alerte\">choc</span>.</li>\n      </ol>\n      <p>Le traitement de <span class=\"kw-ttt\">reperfusion</span> (thrombolyse en 1ʳᵉ intention) est détaillé dans la rubrique Prise en charge.</p>","frequence":0},{"id":"226-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les indications de dosage des D-dimères (TVP, EP) et la notion de seuil d’ajustement à l’âge dans l’EP","contenu":"<p>Les <span class=\"kw-bio\">D-dimères</span> sont des produits spécifiques de la dégradation de la <span class=\"kw-bio\">fibrine</span>. Leur élévation témoigne d'une activation de la coagulation mais survient dans de très nombreuses situations : <strong>ce ne sont pas des marqueurs spécifiques de MTEV</strong>.</p>\n      <p><strong>Indication.</strong> Le dosage permet d'<span class=\"kw-alerte\">éliminer</span> une <span class=\"kw-def\">TVP</span> ou une EP <strong>lorsque la probabilité clinique est non forte</strong> : <span class=\"kw-bio\">VPN 95 %</span>, bonne sensibilité. La VPP est en revanche faible (un test positif n'a aucune valeur diagnostique).</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Seuil de négativité</th></tr></thead>\n        <tbody>\n          <tr><td>Patient &lt;<span class=\"kw-chiffre\"> 50 ans</span></td><td>Négatif si <span class=\"kw-chiffre\">&lt; 500 ng/mL</span></td></tr>\n          <tr><td>Patient <span class=\"kw-chiffre\">≥ 50 ans</span> (<span class=\"kw-def\">seuil ajusté à l'âge</span>)</td><td>Négatif si <span class=\"kw-chiffre\">&lt; âge × 10 ng/mL</span> — ex.<span class=\"kw-chiffre\"> 78 ans</span> : <span class=\"kw-chiffre\">780 ng/mL</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Quand NE PAS doser les <span class=\"kw-bio\">D-dimères</span>.</strong> Pas de dosage si la <span class=\"kw-alerte\">probabilité clinique est forte</span> (imagerie d'emblée), ni dans les situations de faux positifs (cancer, <span class=\"kw-ci\">grossesse</span>, inflammation, post-opératoire, âge &gt;<span class=\"kw-chiffre\"> 80 ans</span>, <span class=\"kw-alerte\">CIVD</span>…). Le dosage est <span class=\"kw-alerte\">non interprétable sous anticoagulant curatif</span>. La sensibilité reste en revanche inchangée chez la <strong>femme enceinte</strong> et le <strong>sujet âgé</strong> : ils doivent être dosés si la probabilité clinique est non forte.</div>","frequence":0},{"id":"226-7","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître la place et les limites de l’échodoppler veineux (TVP, EP)","contenu":"<p>L'<span class=\"kw-imagerie\">échodoppler veineux des membres inférieurs</span> est l'examen de <strong>1ʳᵉ intention pour confirmer une <span class=\"kw-def\">TVP</span></strong> : bonnes sensibilité et spécificité (&gt; <span class=\"kw-chiffre\">95 %</span>), non invasif, non irradiant.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Veine normale</th><th>Signes de <span class=\"kw-def\">TVP</span></th></tr></thead>\n        <tbody>\n          <tr><td>Caillot</td><td>Absence de caillot endoluminal</td><td><span class=\"kw-radio\">Image du caillot veineux</span> (très spécifique)</td></tr>\n          <tr><td>Compressibilité</td><td>Veine <strong>compressible</strong> par la sonde</td><td><span class=\"kw-radio\">Incompressibilité</span> de la veine (signe clé, recherche limitée aux axes fémoral et poplité)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Doppler</span> couleur</td><td>Signal rythmé par la respiration, augmenté par la chasse manuelle</td><td>Remplissage partiel ou <span class=\"kw-radio\">absence de flux</span> dans le segment thrombosé</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/226/echodoppler-tvp.png\" alt=\"Échodoppler veineux d'un membre inférieur montrant une thrombose veineuse profonde — veine incompressible avec thrombus endoluminal\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Échodoppler</span> veineux : <span class=\"kw-etio\">thrombus</span> endoluminal et veine <strong>incompressible</strong> sous la sonde — signe clé de <span class=\"kw-def\">TVP</span>. Source : fiche source EDN item 226.</figcaption>\n      </figure>\n      <div class=\"callout callout-info\"><strong>Limites.</strong> Examen <span class=\"kw-alerte\">très spécifique en proximal mais peu spécifique en distal</span>. Il nécessite un appareillage de haute résolution, une sonde adaptée, un opérateur expérimenté et des conditions techniques optimales. Dans la suspicion d'EP : une <span class=\"kw-def\">TVP proximale</span> retrouvée confirme le diagnostic sans autre examen ; en revanche un <span class=\"kw-alerte\">échodoppler normal n'exclut pas une EP</span>.</div>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/pulmonary-embolism","label":"Radiopaedia : Pulmonary embolism"}]},{"id":"226-8","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître la place et les limites des examens d’imagerie dans l’EP : angiotomodensitométrie thoracique, scintigraphie de ventilation-perfusion, échographie cardiaque trans-thoracique","contenu":"<p>Trois examens d'imagerie structurent le <span class=\"kw-def\">diagnostic positif</span> de l'EP, hiérarchisés selon l'accessibilité et le <span class=\"kw-def\">terrain</span>.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Place et critères</th><th>Limites</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">Angio-TDM thoracique</span><br><em>(multibarettes)</em></td>\n            <td><strong>1ʳᵉ intention</strong> (Se ≈ <span class=\"kw-chiffre\">83 %</span>, Sp &gt; <span class=\"kw-chiffre\">90 %</span>). Critère positif : <span class=\"kw-radio\">lacune endovasculaire</span> ou absence d'opacification d'une artère segmentaire ou proximale. Un examen positif <strong>confirme l'EP quelle que soit la probabilité clinique</strong></td>\n            <td><span class=\"kw-ci\">Allergie aux produits de contraste iodés</span> ; <span class=\"kw-ci\">insuffisance rénale sévère</span>. Si négatif avec probabilité clinique <strong>forte</strong> → poursuivre les explorations</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Scintigraphie de ventilation-perfusion</span></td>\n            <td>Si CI ou difficulté d'accès à l'<span class=\"kw-imagerie\">angio-<span class=\"kw-imagerie\">TDM</span></span>, ou forte suspicion avec <span class=\"kw-imagerie\">angio-<span class=\"kw-imagerie\">TDM</span></span> négatif. <span class=\"kw-def\">Classification</span> <span class=\"kw-def\">PIOPED</span> : examen <strong>normal</strong> → exclut l'EP (Se <span class=\"kw-chiffre\">100 %</span>) ; <span class=\"kw-radio\">mismatch</span> (haute probabilité) = <span class=\"kw-chiffre\">≥ 2</span> défects segmentaires de perfusion sans défect ventilatoire</td>\n            <td>Peu interprétable en cas de <span class=\"kw-alerte\">pathologie cardiorespiratoire préexistante</span> (perturbe la ventilation)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">ETT</span><br><em>(<span class=\"kw-imagerie\">échographie cardiaque</span> trans-thoracique)</em></td>\n            <td>Confirme une EP grave si l'<span class=\"kw-imagerie\">angio-<span class=\"kw-imagerie\">TDM</span></span> n'est pas disponible (probabilité ici toujours forte). Signes <strong>directs</strong> : <span class=\"kw-etio\">thrombus</span> dans les cavités droites. Signes <strong>indirects</strong> : <span class=\"kw-alerte\">dilatation du VD</span>, hypokinésie du VD, septum paradoxal, élévation des PAPs. Sert aussi à stratifier le risque (EP à risque intermédiaire)</td>\n            <td><span class=\"kw-etio\">Thrombus</span> rarement visualisé en <span class=\"kw-imagerie\">ETT</span> (mieux en <span class=\"kw-imagerie\">ETO</span>). L'absence de surcharge droite rend l'EP peu probable</td>\n          </tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/226/angio-tdm-ep-1.png\" alt=\"Angio-TDM thoracique montrant une embolie pulmonaire — lacune endovasculaire dans une artère pulmonaire\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Angio-<span class=\"kw-imagerie\">TDM</span></span> thoracique : <strong>lacune endovasculaire</strong> (défaut d'opacification) au sein d'une artère pulmonaire — signe direct d'EP. Source : fiche source EDN item 226.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/226/angio-tdm-ep-2.png\" alt=\"Angio-TDM thoracique d'une embolie pulmonaire — autre coupe montrant un thrombus artériel pulmonaire\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Angio-<span class=\"kw-imagerie\">TDM</span></span> thoracique, autre coupe : thrombus obstruant une branche artérielle pulmonaire. Source : fiche source EDN item 226.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/226/scintigraphie-vq-mismatch.png\" alt=\"Scintigraphie pulmonaire de ventilation-perfusion montrant un mismatch — défect de perfusion sans défect de ventilation\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Scintigraphie</span> de ventilation-perfusion : <strong>mismatch</strong> — défect de perfusion segmentaire sans défect ventilatoire en regard (haute probabilité PIOPED). Source : fiche source EDN item 226.</figcaption>\n      </figure>\n      <div class=\"callout callout-info\"><strong>Examens abandonnés.</strong> L'<span class=\"kw-imagerie\">angiographie</span> pulmonaire conventionnelle n'est plus pratiquée ; le phléboscanner couplé n'est pas réalisé en routine (<span class=\"kw-clinique\">irradiation</span> trop élevée).</div>","frequence":8},{"id":"226-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les signes de gravité d’une EP et savoir reconnaître les patients pouvant être pris en charge en ambulatoire en cas d’EP","contenu":"<p>La gravité d'une EP s'évalue sur trois plans : l'<strong>hémodynamique</strong>, un <strong><span class=\"kw-def\">score</span> clinique pronostique</strong> et des <strong>marqueurs de souffrance du VD</strong>.</p>\n      <table >\n        <thead><tr><th>Plan</th><th><span class=\"kw-alerte\"><span class=\"kw-def\">Critères de</span> gravité</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Hémodynamique</strong></td><td><span class=\"kw-alerte\">État de choc</span> : <span class=\"kw-chiffre\">PAS &lt; 90 mmHg</span> ou chute &gt; <span class=\"kw-chiffre\">40 mmHg</span> <span class=\"kw-chiffre\">≥ 15 min</span> → EP à haut risque</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Score</span> sPESI</strong><br><em>(mémo 80-90-100-110-C-C)</em></td><td>1 point chacun : âge &gt; <span class=\"kw-chiffre\">80 ans</span> ; SatO₂ &lt; <span class=\"kw-chiffre\">90 %</span> ; PAS &lt; <span class=\"kw-chiffre\">100 mmHg</span> ; FC &gt; <span class=\"kw-chiffre\">110/min</span> ; cancer ; <span class=\"kw-def\">insuffisance cardiaque</span> ou respiratoire chronique. <span class=\"kw-def\">Mortalité</span> à 30 j : <span class=\"kw-chiffre\">1 %</span> si 0 point, <span class=\"kw-chiffre\">10 %</span> si <span class=\"kw-chiffre\">≥ 1</span> point</td></tr>\n          <tr><td><strong>Souffrance du VD</strong></td><td>Dysfonction VD à l'<span class=\"kw-imagerie\">ETT</span> ou à la <span class=\"kw-imagerie\">TDM</span> : rapport <span class=\"kw-chiffre\">VD/VG &gt; 0,9</span>, hypokinésie ; élévation des biomarqueurs : <span class=\"kw-bio\">troponine</span> I ou T, <span class=\"kw-bio\">BNP / NT-proBNP</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Prise en charge ambulatoire.</strong> Une EP de <span class=\"kw-alerte\">faible gravité</span> peut être traitée en ambulatoire : <span class=\"kw-def\">sPESI = 0</span>, <strong>absence de dysfonction du VD</strong> et de <span class=\"kw-alerte\">signe de gravité</span>, <span class=\"kw-def\">terrain</span> et contexte social favorables, faible risque <span class=\"kw-etio\">hémorragique</span>. Toute EP à haut risque ou avec dysfonction VD relève d'une <span class=\"kw-alerte\">hospitalisation</span>.</div>\n      <div class=\"callout callout-info\"><strong>📌 <span class=\"kw-def\">Score HESTIA</span> — alternative LiSA au sPESI.</strong> Score de <strong>11 critères binaires</strong> (instabilité hémodynamique, thrombolyse/embolectomie nécessaire, saignement actif, SpO₂ &lt; <span class=\"kw-chiffre\">90 %</span> sous O₂, EP sous anticoagulant, douleur nécessitant morphinique IV, raison sociale/médicale d'hospitaliser, <span class=\"kw-bio\">DFG &lt; 30 mL/min</span>, <span class=\"kw-alerte\">insuffisance hépatique sévère</span>, <span class=\"kw-clinique\">grossesse</span>, ATCD de <span class=\"kw-alerte\">TIH</span>). Si <strong>tous les critères sont négatifs</strong> → prise en charge ambulatoire possible.</div>","frequence":3},{"id":"226-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de traitement d’une TVP/EP non grave à la phase initiale (voir item 330)","contenu":"<p>L'EP et/ou la <span class=\"kw-def\">TVP</span> proximale sont des <span class=\"kw-alerte\">urgences thérapeutiques</span>. Le traitement repose sur une <span class=\"kw-def\">anticoagulation efficace</span>, à instaurer <strong>dès le diagnostic posé</strong>, voire dès que la probabilité clinique est forte ou intermédiaire (si le risque <span class=\"kw-etio\">hémorragique</span> est faible).</p>\n      <table >\n        <thead><tr><th>Modalité</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ttt\">AOD</span> — 1ʳᵉ intention</strong></td><td>Seuls les <span class=\"kw-ttt\">anti-Xa</span> ont l'AMM et le remboursement dans la MTEV : <span class=\"kw-ttt\">rivaroxaban</span> (Xarelto) et <span class=\"kw-ttt\">apixaban</span> (Eliquis). Voie orale, pas de <span class=\"kw-def\">surveillance</span> <span class=\"kw-ttt\">biologique</span> de routine</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Héparine</span> + relai <span class=\"kw-ttt\">AVK</span></strong></td><td><span class=\"kw-ttt\">HBPM</span> ou <span class=\"kw-ttt\">fondaparinux</span> à privilégier ; <span class=\"kw-ttt\">HNF</span> si CI (<span class=\"kw-bio\">TCA</span> 1,5-2,5). Relai par <span class=\"kw-ttt\">warfarine</span> (<span class=\"kw-bio\">INR</span> 2-3) dès <span class=\"kw-chiffre\">J1</span>, <span class=\"kw-ttt\">héparine</span> arrêtée après <span class=\"kw-chiffre\">≥ 5 jours</span> de chevauchement et 2 <span class=\"kw-bio\">INR</span> cibles</td></tr>\n          <tr><td><strong><span class=\"kw-ci\">Bilan pré-thérapeutique</span></strong></td><td><span class=\"kw-bio\">NFS-plaquettes</span> ; bilan d'hémostase (<span class=\"kw-bio\">fibrinogène</span>, <span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">TCA</span>) ; <span class=\"kw-bio\">créatininémie / DFG</span> ; transaminases ; bilan pré-transfusionnel si risque <span class=\"kw-etio\">hémorragique</span></td></tr>\n          <tr><td><strong>Mesures associées</strong></td><td><span class=\"kw-ttt\">Compression élastique</span> dès le diagnostic de <span class=\"kw-def\">TVP</span> ; <span class=\"kw-clinique\">lever précoce</span><span class=\"kw-chiffre\"> 1 h</span> après l'initiation (sauf <span class=\"kw-alerte\">choc</span> ou hypoxie → alitement)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-ci\">Contre-indications</span> à l'<span class=\"kw-ttt\">anticoagulation</span>.</strong> <span class=\"kw-ci\">Coagulopathie sévère</span> (thrombopénie &lt; <span class=\"kw-chiffre\">30 G/L</span>, hémophilie, <span class=\"kw-bio\">TP</span> &lt; <span class=\"kw-chiffre\">30 %</span>) ; <span class=\"kw-ci\">hémorragie intracrânienne sévère</span> ; <span class=\"kw-ci\">hémorragie active non contrôlable</span>.</div>\n      <p>Remise d'une <strong>carte d'anticoagulé</strong> ; les interactions médicamenteuses sont plus fréquentes avec les <span class=\"kw-ttt\">AVK</span> qu'avec les <span class=\"kw-ttt\">AOD</span> ; pas de régime alimentaire particulier sous <span class=\"kw-ttt\">AVK</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span> · 214 — Thrombopénie</em></p>","frequence":6},{"id":"226-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître les indications et contre-indications de la compression élastique (TVP des membres inférieurs)","contenu":"<p>La <span class=\"kw-ttt\">compression élastique</span> est indiquée <strong>dès que le diagnostic de <span class=\"kw-def\">TVP</span> est posé</strong> (isolée ou associée à une EP). Son but est de prévenir le <span class=\"kw-def\">syndrome post-thrombotique</span>.</p>\n      <ul>\n        <li><strong>Indication :</strong> toute <span class=\"kw-def\">TVP</span> des membres inférieurs, dès la phase initiale.</li>\n        <li><strong>Modalités :</strong> compression de <span class=\"kw-def\">classe 3</span> (<span class=\"kw-chiffre\">30-40 mmHg</span>, chaussettes ou bas), pour une durée minimale de <span class=\"kw-chiffre\">≥ 6 mois</span> (<span class=\"kw-chiffre\">≥ 2 ans</span> selon le collège de cardiologie en cas de <span class=\"kw-def\">TVP</span> proximale).</li>\n        <li>Instaurée dès la phase initiale, elle réduit le risque de syndrome post-<span class=\"kw-etio\">thrombotique</span> d'environ <span class=\"kw-chiffre\">50 %</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Quatre <span class=\"kw-ci\">contre-indications</span>.</strong> <span class=\"kw-ci\">IPS &lt; 0,6</span> (artériopathie) ; <span class=\"kw-ci\">microangiopathie diabétique</span> avec TcPO₂ &lt;<span class=\"kw-chiffre\"> 30 mmHg</span> ; <span class=\"kw-ci\">phlébite bleue</span> (phlegmatia caerulea) ; <span class=\"kw-ci\">thrombose septique</span>. La compression peut par ailleurs favoriser les thromboses veineuses superficielles.</div>","frequence":0},{"id":"226-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les contraceptions contre-indiquées en cas de MTEV (TVP, EP)","contenu":"<p>La <span class=\"kw-def\">contraception œstro-progestative (COP)</span> est <span class=\"kw-alerte\">thrombogène</span> : elle est <span class=\"kw-ci\">contre-indiquée</span> dans plusieurs situations liées à la MTEV.</p>\n      <table >\n        <thead><tr><th>COP <span class=\"kw-ci\">contre-indiquée</span></th><th>Alternatives autorisées (non thrombogènes)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <span class=\"kw-ci\">ATCD personnel de MTEV</span><br>\n              <span class=\"kw-ci\">Thrombophilie</span> <span class=\"kw-etio\">génétique</span> ou acquise<br>\n              <span class=\"kw-ci\">Apparenté du 1ᵉʳ degré</span> ayant eu une MTEV idiopathique avant <span class=\"kw-chiffre\">45 ans</span>\n            </td>\n            <td>\n              <span class=\"kw-ttt\">Micro-progestatif oral</span><br>\n              <span class=\"kw-ttt\">Implant à la progestérone</span><br>\n              <span class=\"kw-ttt\">Stérilet (DIU) à la progestérone</span><br>\n              <span class=\"kw-ttt\">Stérilet (DIU) au cuivre</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Conduite à tenir.</strong> Devant une MTEV survenant sous COP : arrêt de la COP <strong>sans <span class=\"kw-alerte\">urgence</span></strong> (finir la <span class=\"kw-bio\">plaquette</span>), puis relai par une contraception non thrombogène proposée par le gynécologue. Une <span class=\"kw-ci\">contraception efficace</span> est <strong>indispensable</strong> sous traitement <span class=\"kw-ttt\">anticoagulant</span> (risque <span class=\"kw-ci\">tératogène</span> des <span class=\"kw-ttt\">AVK</span> et des <span class=\"kw-ttt\">AOD</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p>","frequence":0},{"id":"226-13","rang":"A","rubrique":"Prise en charge","titre":"Connaître les situations nécessitant une prévention de la MTEV","contenu":"<p>La prévention de la MTEV repose sur des mesures non médicamenteuses (mobilisation, compression) et, dans certaines situations à risque, une <span class=\"kw-ttt\">anticoagulation préventive</span> par <span class=\"kw-ttt\">HBPM</span> ou <span class=\"kw-ttt\">fondaparinux</span>.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Milieu médical</strong></td>\n            <td>Patients &gt; <span class=\"kw-chiffre\">40 ans</span>, hospitalisés &gt; <span class=\"kw-chiffre\">3 jours</span>, pour : <span class=\"kw-etio\">IDM</span>, <span class=\"kw-etio\">AVC ischémique</span>, <span class=\"kw-def\">insuffisance cardiaque</span> ou respiratoire aiguë ; affection rhumatologique, <span class=\"kw-etio\">MICI</span> ou infection associée à un FDR. Anticoagulation préventive <span class=\"kw-chiffre\">7 à 14 jours</span></td>\n          </tr>\n          <tr>\n            <td><strong>Post-opératoire</strong></td>\n            <td><strong>Risque faible</strong> (<span class=\"kw-ttt\">chirurgie</span> mineure, &lt;<span class=\"kw-chiffre\"> 40 ans</span>, sans FDR) → <span class=\"kw-alerte\">pas d'anticoagulation</span><br><strong>Risque modéré</strong> (chirurgie générale, &gt;<span class=\"kw-chiffre\"> 40 ans</span>) → <span class=\"kw-ttt\">HBPM</span> préventive<br><strong>Risque élevé</strong> (chirurgie hanche/genou, carcinologique, ATCD de MTEV) → HBPM préventive ; prolongée jusqu'à <span class=\"kw-chiffre\">5 semaines</span> en chirurgie de hanche</td>\n          </tr>\n          <tr>\n            <td><strong>Voyage &gt;<span class=\"kw-chiffre\"> 6 h</span></strong></td>\n            <td>Conseils simples (hydratation, contraction des mollets, pas de vêtements serrés) ; si FDR associés : compression de <span class=\"kw-chiffre\">classe 2</span>-3 ± <span class=\"kw-ttt\">HBPM</span> préventive avant le départ</td>\n          </tr>\n        </tbody>\n      </table>","frequence":2},{"id":"226-14","rang":"B","rubrique":"Prise en charge","titre":"Savoir déterminer la durée du traitement anticoagulant (TVP proximale et EP)","contenu":"<p>La durée du traitement <span class=\"kw-ttt\">anticoagulant</span> est de <strong><span class=\"kw-chiffre\">3 mois</span> minimum</strong>. Elle s'allonge en fonction du <span class=\"kw-def\">caractère provoqué ou non</span> de la MTEV et du <span class=\"kw-def\">risque hémorragique</span>.</p>\n      <table >\n        <thead><tr><th>Durée</th><th>Situations</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Courte</strong> (<span class=\"kw-chiffre\">3 à 6 mois</span>)</td><td>1ᵉʳ épisode d'EP ou de <span class=\"kw-def\">TVP</span> proximale <span class=\"kw-def\">provoquée par un facteur majeur transitoire</span> ; risque <span class=\"kw-etio\">hémorragique</span> élevé ; <span class=\"kw-def\">TVP</span> distale</td></tr>\n          <tr><td><strong>Non limitée</strong><br><em>(si risque <span class=\"kw-etio\">hémorragique</span> faible/modéré)</em></td><td>EP ou <span class=\"kw-def\">TVP</span> proximale <span class=\"kw-alerte\">non provoquée récidivante</span> ; EP ou <span class=\"kw-def\">TVP</span> proximale avec <span class=\"kw-alerte\">facteur persistant majeur</span> ; 1ᵉʳ épisode d'EP à risque élevé non provoquée</td></tr>\n          <tr><td><strong>Incertaine</strong><br><em>(<span class=\"kw-chiffre\">6 mois</span> minimum, voire non limitée)</em></td><td>1ᵉʳ épisode d'EP à risque faible/intermédiaire ou de <span class=\"kw-def\">TVP</span> proximale, non provoquée, avec ou sans facteur mineur</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Logique du risque de récidive.</strong> Risque élevé si facteur persistant majeur ou MTEV non provoquée → traitement prolongé. Risque faible si facteur transitoire majeur → traitement court. Les facteurs mineurs influencent peu le risque de récidive.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":1},{"id":"226-15","rang":"B","rubrique":"Étiologies","titre":"Savoir porter l’indication d’une recherche de cancer en cas de MTEV (TVP, EP)","contenu":"<p>L'<span class=\"kw-def\">incidence</span> de cancer après une MTEV varie de <span class=\"kw-chiffre\">6 à 28 %</span>, significativement plus élevée en cas de <span class=\"kw-etio\">MTEV idiopathique ou récidivante</span>, et surtout dans les <span class=\"kw-chiffre\">6 à 12 premiers mois</span>.</p>\n      <p><strong>Indication de la recherche :</strong> <span class=\"kw-def\">MTEV non provoquée</span>, surtout si patient &gt; <span class=\"kw-chiffre\">40 ans</span> ou en cas de bilan de thrombophilie négatif.</p>\n      <table >\n        <thead><tr><th>Bilan</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Systématique</strong></td><td><span class=\"kw-clinique\">Examen clinique complet</span> (touchers pelviens) ; <span class=\"kw-imagerie\">RXT</span> si <span class=\"kw-imagerie\">angioscanner</span> non réalisé ; recherche de sang dans les selles ; <span class=\"kw-bio\">NFS, CRP</span> ; chez l'homme <span class=\"kw-bio\">PSA</span> ; chez la femme examen gynécologique avec frottis, <span class=\"kw-imagerie\">mammographie</span>, <span class=\"kw-imagerie\">échographie pelvienne</span></td></tr>\n          <tr><td><strong>Non systématique</strong></td><td>Endoscopies digestives, <span class=\"kw-imagerie\">échographie</span> abdomino-pelvienne, body-<span class=\"kw-imagerie\">TDM</span> — seulement s'il existe des signes d'orientation clinique</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Surveillance</span>.</strong> Une surveillance clinique répétée sur <span class=\"kw-chiffre\">≥ 1 an</span> est indispensable après une MTEV non provoquée.</div>","frequence":2},{"id":"226-16","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Savoir évoquer les complications à long terme de la MTEV (syndrome post-thrombotique, HTAP)","contenu":"<p>Deux complications tardives sont à connaître, l'une veineuse après <span class=\"kw-def\">TVP</span>, l'autre artérielle pulmonaire après EP.</p>\n      <table >\n        <thead><tr><th></th><th>Syndrome post-<span class=\"kw-etio\">thrombotique</span></th><th>HTP post-<span class=\"kw-etio\">embolique</span></th></tr></thead>\n        <tbody>\n          <tr><td>Suit</td><td>Une <span class=\"kw-def\">TVP</span></td><td>Une <span class=\"kw-def\">EP</span></td></tr>\n          <tr><td>Fréquence</td><td><span class=\"kw-chiffre\">20-50 %</span> développent une IVC à<span class=\"kw-chiffre\"> 5-10 ans</span> ; <span class=\"kw-chiffre\">5-10 %</span> une forme sévère — risque majeur si thrombose ilio-fémorale</td><td>Rare (<span class=\"kw-chiffre\">2-3 %</span>) mais grave</td></tr>\n          <tr><td>Mécanisme</td><td>Obstruction veineuse résiduelle et/ou <span class=\"kw-def\">destruction valvulaire</span> → reflux profond → insuffisance veineuse chronique</td><td>Persistance d'une obstruction significative du lit artériel pulmonaire</td></tr>\n          <tr><td>Clinique</td><td><span class=\"kw-clinique\">Lourdeur de jambe</span>, <span class=\"kw-clinique\">œdème</span>, troubles trophiques, ulcères ; sévérité évaluée par le <span class=\"kw-def\">score de Villalta</span></td><td><span class=\"kw-clinique\">Dyspnée persistante</span> à distance d'une EP (&gt;<span class=\"kw-chiffre\"> 3 mois</span> après le traitement)</td></tr>\n          <tr><td>Prévention</td><td>Anticoagulation efficace + <span class=\"kw-ttt\">compression élastique</span> dès la phase initiale</td><td><span class=\"kw-def\">Dépistage</span> devant toute <span class=\"kw-clinique\">dyspnée</span> persistante post-EP (voir objectif suivant)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 227 — Insuffisance veineuse chronique - varices</em></p>","frequence":1},{"id":"226-17","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître la complication à dépister avant d’arrêter un traitement anticoagulant pour EP","contenu":"<p>La complication à dépister avant d'arrêter une <span class=\"kw-ttt\">anticoagulation</span> prescrite pour EP est l'<span class=\"kw-def\">hypertension pulmonaire post-embolique (HTP-PE)</span> — rare (<span class=\"kw-chiffre\">2-3 %</span>) mais grave, liée à la persistance d'une obstruction significative du lit artériel pulmonaire.</p>\n      <p><strong>Signe d'appel :</strong> une <span class=\"kw-clinique\">dyspnée persistante</span> à distance de l'EP, &gt; <span class=\"kw-chiffre\">3 mois</span> après le traitement.</p>\n      <p><strong>Démarche diagnostique :</strong></p>\n      <ol>\n        <li><span class=\"kw-imagerie\">ETT</span> : estimation de la PAP systolique et recherche de signes indirects (dilatation et dysfonction du VD).</li>\n        <li>Si <span class=\"kw-alerte\">PAPs élevée</span> ou risque échographique d'HTAP intermédiaire/élevé → <span class=\"kw-imagerie\">scintigraphie de ventilation-perfusion</span>.</li>\n        <li>Si <span class=\"kw-radio\">défects perfusionnels</span> à la <span class=\"kw-imagerie\">scintigraphie</span> → confirmation par <span class=\"kw-imagerie\">cathétérisme cardiaque droit</span>.</li>\n      </ol>\n      <div class=\"callout callout-info\"><strong>Prise en charge.</strong> Le traitement de référence de l'HTP post-<span class=\"kw-etio\">embolique</span> est l'<span class=\"kw-ttt\">endartériectomie pulmonaire</span>.</div>","frequence":0},{"id":"226-18","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge une thrombose veineuse superficielle","contenu":"<p>La <span class=\"kw-def\">thrombose veineuse superficielle (TVS)</span> survient le plus souvent sur des veines <span class=\"kw-etio\">variqueuses</span>, habituellement sur le trajet de la grande veine saphène. Cliniquement : <span class=\"kw-clinique\">cordon rouge induré</span>, douloureux, <span class=\"kw-etio\">inflammatoire</span>.</p>\n      <div class=\"callout callout-warn\"><strong>Quand chercher une cause.</strong> Une TVS sur veines <strong>apparemment saines, non variqueuses</strong>, doit faire rechercher une cause systémique : <span class=\"kw-etio\">cancer</span>, <span class=\"kw-etio\">maladie de Buerger</span>, <span class=\"kw-etio\">maladie de Behçet</span>, hémopathie, pathologie <span class=\"kw-etio\">auto-immune</span>, thrombophilie.</div>\n      <p><strong>Risque.</strong> La TVS est habituellement sans danger, sauf si la thrombose de la saphène interne <strong>s'étend jusqu'à la crosse</strong>. Une <span class=\"kw-alerte\">TVP associée</span> est présente dans <span class=\"kw-chiffre\">5-10 %</span> des cas → <span class=\"kw-imagerie\">échodoppler veineux</span> indispensable pour la rechercher.</p>\n      <table >\n        <thead><tr><th>Prise en charge</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Systématique</strong></td><td><span class=\"kw-ttt\">Anti-inflammatoires locaux</span> ; <span class=\"kw-ttt\">contention veineuse</span> (préférer le bandage) ; <span class=\"kw-alerte\">anticoagulation non systématique</span></td></tr>\n          <tr><td><strong>Anticoagulation curative ou <span class=\"kw-ttt\">chirurgie</span></strong></td><td>Si TVS étendue à la <span class=\"kw-alerte\">jonction grande saphène-veine fémorale</span></td></tr>\n          <tr><td><strong>Fondaparinux préventif <span class=\"kw-chiffre\">45 jours</span></strong></td><td>Si TVS isolée &gt; <span class=\"kw-chiffre\">5 cm</span> de longueur, située à &gt; <span class=\"kw-chiffre\">3 cm</span> de la jonction saphéno-fémorale</td></tr>\n        </tbody>\n      </table>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p>Le diagnostic d'<span class=\"kw-def\">EP</span> doit être établi en <span class=\"kw-chiffre\">&lt; 24 h</span>. L'<span class=\"kw-def\">EP</span> et/ou la <span class=\"kw-def\">TVP proximale</span> sont des <span class=\"kw-alerte\">urgences thérapeutiques</span>.</p><p><strong>EP à haut risque <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> vitale</span></strong></p><p><span class=\"kw-ttt\">Thrombolyse</span> en 1ʳᵉ intention dès l'orientation, <span class=\"kw-imagerie\">angio-TDM</span> de confirmation dès stabilisation</p><ul><li><span class=\"kw-alerte\">État de choc</span> : <span class=\"kw-chiffre\">PAS &lt; 90 mmHg</span> ou chute <span class=\"kw-chiffre\">&gt; 40 mmHg ≥ 15 min</span></li><li>Forme rare (≈ <span class=\"kw-chiffre\">5 %</span>) mais <span class=\"kw-alerte\">mortalité 25-50 %</span></li><li>Patient instable : <span class=\"kw-imagerie\">ETT au lit</span> (jamais transporté au <span class=\"kw-imagerie\">scanner</span>) → <span class=\"kw-alerte\">dilatation/dysfonction du VD</span></li></ul><p><strong>EP / TVP proximale non grave <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> thérapeutique</span></strong></p><p><span class=\"kw-ttt\">Compression élastique</span> dès le diagnostic de <span class=\"kw-def\">TVP</span> + <span class=\"kw-ttt\">lever précoce</span> à<span class=\"kw-chiffre\"> 1 h</span></p><ul><li><span class=\"kw-ttt\">Anticoagulation efficace</span> dès le diagnostic posé</li><li>Voire dès une <span class=\"kw-def\">probabilité clinique</span> forte/intermédiaire si risque <span class=\"kw-etio\">hémorragique</span> faible</li></ul>","hospit":"<p><strong>TVP <span class=\"q\">— ambulatoire par défaut</span></strong></p><ul><li>Majorité des cas en <span class=\"kw-clinique\">ambulatoire</span></li><li>Hospit si : <span class=\"kw-bio\">clairance &lt; 30 mL/min</span>, risque <span class=\"kw-etio\">hémorragique</span> / <span class=\"kw-alerte\">hémorragie active</span>, <span class=\"kw-def\">TVP</span> sous <span class=\"kw-ttt\">anticoagulant</span>, contexte médico-social défavorable</li><li><span class=\"kw-alerte\">TVP proximale sévère</span> : phlegmatia caerulea, localisation iliocave, <span class=\"kw-def\">TVP</span> bilatérale</li></ul><p><strong>EP <span class=\"q\">— selon la gravité</span></strong></p><ul><li>Ambulatoire possible si <span class=\"kw-def\">sPESI = 0</span>, pas de <span class=\"kw-alerte\">dysfonction VD</span>, <span class=\"kw-def\">terrain</span>/contexte favorables, faible risque <span class=\"kw-etio\">hémorragique</span></li><li><span class=\"kw-alerte\">EP à haut risque</span> ou dysfonction VD → <span class=\"kw-alerte\">hospitalisation</span> (<span class=\"kw-alerte\">USI</span> / réanimation)</li></ul><p><strong>TVP pelvienne</strong></p><ul><li><span class=\"kw-alerte\">Hospitalisation systématique</span> (complication d'endométrite, <span class=\"kw-alerte\">urgence</span> thérapeutique)</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">État de choc</span> : <span class=\"kw-chiffre\">PAS &lt; 90 mmHg</span> → <span class=\"kw-def\">EP à haut risque</span> (<span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">25-50 %</span>)</li><li><span class=\"kw-alerte\">Dysfonction du VD</span> : rapport <span class=\"kw-chiffre\">VD/VG &gt; 0,9</span>, hypokinésie à l'<span class=\"kw-imagerie\">ETT/TDM</span></li><li>Élévation des biomarqueurs : <span class=\"kw-bio\">troponine</span>, <span class=\"kw-bio\">BNP / NT-proBNP</span></li><li><span class=\"kw-def\">sPESI ≥ 1</span> : âge <span class=\"kw-chiffre\">&gt; 80 ans</span>, <span class=\"kw-clinique\">SatO₂</span> <span class=\"kw-chiffre\">&lt; 90 %</span>, <span class=\"kw-chiffre\">PAS &lt; 100 mmHg</span>, <span class=\"kw-chiffre\">FC &gt; 110/min</span>, cancer, IC/IR chronique</li><li><span class=\"kw-clinique\">Dyspnée brutale</span> + auscultation normale = <span class=\"kw-alerte\">EP jusqu'à preuve du contraire</span></li><li><span class=\"kw-clinique\">Syncope</span> (bas débit systémique)</li><li><span class=\"kw-alerte\">Phlegmatia caerulea</span> (phlébite bleue, ischémie de membre) ; <span class=\"kw-alerte\">phlegmatia alba dolens</span> (forme sévère de TVP)</li></ul>","principes":"<p>L'<span class=\"kw-ttt\">anticoagulation efficace</span> est instaurée <strong>dès le diagnostic posé</strong> (voire dès une <span class=\"kw-def\">probabilité clinique</span> forte/intermédiaire si faible risque <span class=\"kw-etio\">hémorragique</span>). Durée <strong>minimale <span class=\"kw-chiffre\">3 mois</span></strong>, modulée par le caractère provoqué et le risque de récidive.</p><p><strong>Anticoagulation curative</strong></p><p><span class=\"kw-ci\">CI</span> : <span class=\"kw-ci\">thrombopénie &lt; 30 G/L</span>, <span class=\"kw-ci\">TP &lt; 30 %</span>, hémophilie, <span class=\"kw-ci\">hémorragie intracrânienne ou active non contrôlable</span></p><ul><li><strong>1ʳᵉ intention</strong> : <span class=\"kw-ttt\">AOD anti-Xa</span> — <span class=\"kw-ttt\">rivaroxaban</span>, <span class=\"kw-ttt\">apixaban</span> (seuls AMM + remboursés dans la MTEV)</li><li>Alternative : <span class=\"kw-ttt\">HBPM</span> ou <span class=\"kw-ttt\">fondaparinux</span> + relai <span class=\"kw-ttt\">AVK</span> (<span class=\"kw-bio\">INR</span> 2-3, chevauchement ≥ <span class=\"kw-chiffre\">5 j</span>)</li><li><span class=\"kw-ttt\">HNF</span> si CI aux précédents (<span class=\"kw-bio\">TCA</span> 1,5-2,5)</li><li>Cancer : <span class=\"kw-ttt\">HBPM</span> au long cours (ou certains <span class=\"kw-ttt\">AOD</span> hors cancer digestif/uro-génital)</li></ul><p><strong>Mesures associées</strong></p><ul><li><span class=\"kw-ttt\">Compression élastique classe 3</span> dès le diagnostic de <span class=\"kw-def\">TVP</span> (≥ <span class=\"kw-chiffre\">6 mois</span>)</li><li><span class=\"kw-ttt\">Lever précoce</span><span class=\"kw-chiffre\"> 1 h</span> après l'initiation (sauf <span class=\"kw-alerte\">choc</span>/hypoxie → alitement)</li><li>Carte d'anticoagulé ; <span class=\"kw-ci\">contraception efficace</span> (risque tératogène <span class=\"kw-ci\">AVK</span> / <span class=\"kw-ci\">AOD</span>)</li></ul><p><strong>EP à haut risque <span class=\"q\">— <span class=\"kw-ttt\">reperfusion</span></span></strong></p><ul><li><span class=\"kw-ttt\">Thrombolyse</span> en 1ʳᵉ intention (toujours suivie d'une <span class=\"kw-ttt\">anticoagulation efficace</span>)</li><li><span class=\"kw-ttt\">Embolectomie chirurgicale</span> ou <span class=\"kw-ttt\">reperfusion</span> percutanée si <span class=\"kw-ci\">CI absolue</span> ou échec de la <span class=\"kw-ttt\">thrombolyse</span></li><li><span class=\"kw-ttt\">Filtre cave</span> temporaire si <span class=\"kw-ci\">CI formelle aux anticoagulants</span> ou récidive sous traitement bien conduit</li></ul>","suivi":"<p><strong>Durée du traitement</strong></p><ul><li><strong>Courte (<span class=\"kw-chiffre\">3-6 mois</span>)</strong> : 1ᵉʳ épisode provoqué par facteur majeur transitoire ; risque <span class=\"kw-etio\">hémorragique</span> élevé ; <span class=\"kw-def\">TVP distale</span></li><li><strong>Non limitée</strong> : MTEV <span class=\"kw-alerte\">non provoquée récidivante</span> ou facteur <span class=\"kw-alerte\">persistant majeur</span></li><li><span class=\"kw-def\">Réévaluation</span> régulière du rapport bénéfice / risque <span class=\"kw-etio\">hémorragique</span></li></ul><p><strong>Recherche de cancer</strong></p><ul><li>Si <span class=\"kw-etio\">MTEV non provoquée</span>, surtout &gt; <span class=\"kw-chiffre\">40 ans</span> ou bilan de thrombophilie négatif</li><li>Bilan systématique : <span class=\"kw-clinique\">examen clinique</span> complet, <span class=\"kw-bio\">NFS-CRP</span>, dépistages selon âge/sexe</li><li><span class=\"kw-def\">Surveillance</span> clinique <span class=\"kw-chiffre\">≥ 1 an</span></li></ul><p><strong>Avant arrêt de l'<span class=\"kw-ttt\">anticoagulation</span> (EP)</strong></p><ul><li>Dépister l'<span class=\"kw-def\">HTP post-embolique</span> devant une <span class=\"kw-clinique\">dyspnée persistante</span> &gt; <span class=\"kw-chiffre\">3 mois</span></li><li>Démarche : <span class=\"kw-imagerie\">ETT</span> → <span class=\"kw-imagerie\">scintigraphie V/Q</span> → <span class=\"kw-imagerie\">cathétérisme cardiaque droit</span></li><li>Complication veineuse : <span class=\"kw-def\">syndrome post-thrombotique</span> (<span class=\"kw-def\">score</span> de <span class=\"kw-def\">Villalta</span>)</li></ul>"},"liensGlobaux":[{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/14.%20Embolie%20pulmonaire.pdf","label":"CeMIR — 14. embolie pulmonaire"},{"href":"https://cep-1f48c.kxcdn.com/wp-content/uploads/2023/07/ITEM_226_MALADIE_THROMBO-EMBOLIQUE_VEINEUSE_2023.pdf","label":"Collège (CEP) — Item 226 maladie thrombo embolique veineuse 2023"},{"href":"https://www.sfcardio.fr/page/chapitre-19-item-226-thrombose-veineuse-profonde-et-embolie-pulmonaire","label":"SFC — Chapitre 19 item 226 thrombose veineuse profonde et embolie pulmonaire"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Suspicion d'embolie pulmonaire — Adulte — premier tri sur la stabilité hémodynamique","detail":"<h4>CAT — suspicion d'<span class=\"kw-alerte\">embolie pulmonaire</span> — Stabilité hémodynamique → probabilité clinique → <span class=\"kw-bio\">D-dimères</span> → imagerie</h4>","branches":[{"to":"q-instable","label":"Instabilité hémodynamique (état de choc)","color":"red"},{"to":"q-proba","label":"Patient stable","color":"blue"}]},{"id":"q-instable","kind":"decision","label":"ETT au lit — surcharge des cavités droites ? — Patient instable : on ne le transporte pas au scanner","branches":[{"to":"t-haut-risque","label":"Dysfonction / dilatation du VD","color":"red"},{"to":"t-autre-choc","label":"Pas de surcharge droite","color":"amber"}]},{"id":"t-haut-risque","kind":"terminal","label":"EP à haut risque","color":"red","detail":"<h4>Définition</h4><ul><li><span class=\"kw-alerte\">État de choc</span> : <span class=\"kw-chiffre\">PAS &lt; 90 mmHg</span> ou chute <span class=\"kw-chiffre\">&gt; 40 mmHg ≥ 15 min</span> ; <span class=\"kw-alerte\">mortalité 25-50 %</span></li></ul><h4>Confirmation</h4><ul><li><span class=\"kw-imagerie\">ETT au lit</span> : <span class=\"kw-alerte\">dilatation / dysfonction du VD</span> (signes indirects) ; <span class=\"kw-imagerie\">angio-TDM</span> dès stabilisation</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Thrombolyse</span> en 1ʳᵉ intention, suivie d'une <span class=\"kw-ttt\">anticoagulation efficace</span></li><li><span class=\"kw-ttt\">Embolectomie chirurgicale</span> ou <span class=\"kw-ttt\">reperfusion</span> percutanée si <span class=\"kw-ci\">CI absolue</span> ou échec de la <span class=\"kw-ttt\">thrombolyse</span></li></ul><h4>Renvoi</h4><ul><li>Item 330 (prescription et <span class=\"kw-def\">surveillance</span> des médicaments)</li></ul>"},{"id":"t-autre-choc","kind":"terminal","label":"Autre cause de choc","color":"amber","detail":"<h4>Interprétation</h4><ul><li>L'absence de <span class=\"kw-alerte\">surcharge des cavités droites</span> à l'<span class=\"kw-imagerie\">ETT</span> rend l'<span class=\"kw-def\">EP à haut risque</span> peu probable</li></ul><h4>Conduite</h4><ul><li>Rechercher une <span class=\"kw-etio\">autre cause de choc</span> (cardiogénique, hypovolémique, septique, obstructif)</li></ul><h4>Renvoi</h4><ul><li>Item 332 (<span class=\"kw-alerte\">état de choc</span>)</li></ul>"},{"id":"q-proba","kind":"decision","label":"Probabilité clinique (Wells / Genève) ? — Score de Wells ou de Genève révisé","branches":[{"to":"q-ddim","label":"Probabilité non forte (faible / intermédiaire)","color":"blue"},{"to":"t-imagerie-emblee","label":"Probabilité forte","color":"amber"}]},{"id":"q-ddim","kind":"decision","label":"D-dimères (seuil ajusté à l'âge) ? — Seuil ajusté au-delà de 50 ans","branches":[{"to":"t-exclue","label":"D-dimères négatifs","color":"green"},{"to":"q-imagerie","label":"D-dimères positifs","color":"amber"}]},{"id":"t-exclue","kind":"terminal","label":"EP exclue","color":"green","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-bio\">D-dimères</span> négatifs : <span class=\"kw-chiffre\">&lt; 500 ng/mL</span> (&lt;<span class=\"kw-chiffre\"> 50 ans</span>) ou <span class=\"kw-chiffre\">&lt; âge × 10</span> (<span class=\"kw-chiffre\">≥ 50 ans</span>) → <span class=\"kw-bio\">VPN 95 %</span></li></ul><h4>Conduite</h4><ul><li>Diagnostic d'<span class=\"kw-def\">EP</span> éliminé — pas d'imagerie</li></ul><h4>Pièges</h4><ul><li><span class=\"kw-bio\">D-dimères</span> non interprétables sous <span class=\"kw-ttt\">anticoagulant curatif</span></li><li>Nombreux faux positifs : <span class=\"kw-etio\">cancer</span>, <span class=\"kw-etio\">grossesse</span>, <span class=\"kw-etio\">inflammation</span>, post-opératoire</li></ul>"},{"id":"q-imagerie","kind":"decision","label":"Angio-TDM thoracique ? — Imagerie de confirmation","branches":[{"to":"t-confirmee","label":"Angio-TDM positif (lacune)","color":"red"},{"to":"t-ecartee","label":"Angio-TDM négatif","color":"green"}]},{"id":"t-confirmee","kind":"terminal","label":"EP confirmée","color":"red","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-imagerie\">Angio-TDM</span> positif : <span class=\"kw-radio\">lacune endovasculaire</span> / absence d'opacification segmentaire → confirme l'<span class=\"kw-def\">EP</span> quelle que soit la probabilité</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Anticoagulation efficace</span> dès le diagnostic — <span class=\"kw-ttt\">AOD anti-Xa</span> (<span class=\"kw-ttt\">rivaroxaban</span>, <span class=\"kw-ttt\">apixaban</span>) en 1ʳᵉ intention</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Évaluer la gravité (<span class=\"kw-def\">sPESI</span>, <span class=\"kw-alerte\">dysfonction VD</span>) pour l'orientation (ambulatoire <span class=\"kw-bio\">vs</span> <span class=\"kw-alerte\">hospitalisation</span>)</li></ul><h4>Renvoi</h4><ul><li>Item 330 (prescription et <span class=\"kw-def\">surveillance</span> des médicaments)</li></ul>"},{"id":"t-ecartee","kind":"terminal","label":"EP écartée","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-imagerie\">Angio-TDM</span> négatif avec probabilité <strong>non forte</strong> → <span class=\"kw-def\">EP</span> exclue</li></ul><h4>Nuance</h4><ul><li>Si la probabilité avait été <strong>forte</strong>, un <span class=\"kw-imagerie\">angio-TDM</span> négatif imposerait de poursuivre (<span class=\"kw-imagerie\">scintigraphie V/Q</span>)</li></ul>"},{"id":"t-imagerie-emblee","kind":"terminal","label":"Imagerie d'emblée (probabilité forte)","color":"amber","detail":"<h4>Conduite</h4><ul><li>Probabilité <strong>forte</strong> → pas de <span class=\"kw-bio\">D-dimères</span>, <span class=\"kw-imagerie\">imagerie d'emblée</span></li></ul><h4>Examen</h4><ul><li><span class=\"kw-imagerie\">Angio-TDM thoracique</span> en 1ʳᵉ intention ; positif → confirme l'<span class=\"kw-def\">EP</span></li></ul><h4>Si négatif</h4><ul><li>Probabilité forte maintenue → poursuivre : <span class=\"kw-imagerie\">scintigraphie V/Q</span>, <span class=\"kw-imagerie\">échodoppler veineux</span> (une <span class=\"kw-def\">TVP proximale</span> confirme l'<span class=\"kw-def\">EP</span> sans autre examen)</li></ul>"}]},"cards":[{"i":"59edd416dcdd","n":226,"o":"226-1","u":"Définition","t":"Connaître la définition d’une thrombose veineuse profonde (TVP), d’une TVP proximale, d’une TVP distale, d’une embolie pulmonaire (EP), d’une EP à haut risque","q":"Quelle est la définition d'une embolie pulmonaire (EP) ?","a":"<p>Une embolie pulmonaire (EP) est l'<strong>obstruction des artères pulmonaires</strong> ou de leurs branches par un ou des thrombus.</p>"},{"i":"96896aea4321","n":226,"o":"226-1","u":"Définition","t":"Connaître la définition d’une thrombose veineuse profonde (TVP), d’une TVP proximale, d’une TVP distale, d’une embolie pulmonaire (EP), d’une EP à haut risque","q":"Quelle est la définition d'une thrombose veineuse profonde (TVP) ?","a":"<p>Une thrombose veineuse profonde (TVP) est l'<strong>obstruction thrombotique d'un tronc veineux profond</strong>, localisée le plus souvent aux membres inférieurs.</p>"},{"i":"b14c7e411639","n":226,"o":"226-1","u":"Définition","t":"Connaître la définition d’une thrombose veineuse profonde (TVP), d’une TVP proximale, d’une TVP distale, d’une embolie pulmonaire (EP), d’une EP à haut risque","q":"Comment définit-on une TVP distale ?","a":"<p>Une TVP distale est une <strong>thrombose sous-poplitée</strong>, affectant les veines jambières (tibiale antérieure et postérieure, fibulaire) et surales (soléaire, gastrocnémienne).</p>"},{"i":"eaaaad52e2d7","n":226,"o":"226-1","u":"Définition","t":"Connaître la définition d’une thrombose veineuse profonde (TVP), d’une TVP proximale, d’une TVP distale, d’une embolie pulmonaire (EP), d’une EP à haut risque","q":"Comment définit-on une TVP proximale ?","a":"<p>Une TVP proximale est une <strong>thrombose sus-poplitée</strong>, c'est-à-dire qu'elle affecte les veines poplitée, fémorale, iliaque ou cave. Elle est associée à un risque élevé d'embolie pulmonaire.</p>"},{"i":"ed9975e26f08","n":226,"o":"226-1","u":"Définition","t":"Connaître la définition d’une thrombose veineuse profonde (TVP), d’une TVP proximale, d’une TVP distale, d’une embolie pulmonaire (EP), d’une EP à haut risque","q":"Qu'est-ce qu'une embolie pulmonaire à haut risque ?","a":"<p>Une embolie pulmonaire à haut risque est une EP définie par la présence d'un <strong>état de choc</strong>, caractérisée par une <stong>pression artérielle systolique (PAS) inférieure à 90 mmHg</stong>. Cette forme est rare mais présente une forte mortalité.</p>"},{"i":"0e077bba12e6","n":226,"o":"226-10","u":"Prise en charge","t":"Connaître les principes de traitement d’une TVP/EP non grave à la phase initiale (voir item 330)","q":"Quel bilan pré-thérapeutique est nécessaire avant d'initier un traitement anticoagulant pour une TVP/EP non grave ?","a":"<p>Le bilan pré-thérapeutique comprend :</p><ul><li><strong>NFS-plaquettes</strong>.</li><li>Bilan d'hémostase : <strong>fibrinogène, TP, TCA</strong>.</li><li><strong>Créatininémie / DFG</strong>.</li><li><strong>Transaminases</strong>.</li><li><strong>Bilan pré-transfusionnel</strong> si risque hémorragique.</li></ul>"},{"i":"5e4a171a0fb1","n":226,"o":"226-10","u":"Prise en charge","t":"Connaître les principes de traitement d’une TVP/EP non grave à la phase initiale (voir item 330)","q":"Quels sont les anticoagulants de première intention à privilégier pour le traitement initial d'une TVP/EP non grave, et quelles sont leurs caractéristiques principales ?","a":"<p>Les anticoagulants de première intention sont les <strong>AOD (anticoagulants oraux directs)</strong>, et plus spécifiquement les <strong>anti-Xa</strong> comme le <strong>rivaroxaban (Xarelto)</strong> et l'<strong>apixaban (Eliquis)</strong>. Leurs caractéristiques principales sont :</p><ul><li>Ils sont administrés par <strong>voie orale</strong>.</li><li>Ils ne nécessitent <strong>pas de surveillance biologique de routine</strong>.</li></ul>"},{"i":"82f50d23b6c3","n":226,"o":"226-10","u":"Prise en charge","t":"Connaître les principes de traitement d’une TVP/EP non grave à la phase initiale (voir item 330)","q":"Quelle est l'approche thérapeutique initiale recommandée en cas de suspicion forte ou intermédiaire de TVP/EP (non grave), avant même la confirmation diagnostique, en l'absence de risque hémorragique élevé ?","a":"<p>Devant une suspicion forte ou intermédiaire de TVP/EP non grave et un risque hémorragique faible, il est recommandé d'instaurer une <strong>anticoagulation efficace</strong>.</p>"},{"i":"bfa71468af57","n":226,"o":"226-10","u":"Prise en charge","t":"Connaître les principes de traitement d’une TVP/EP non grave à la phase initiale (voir item 330)","q":"En cas de traitement par héparine suivi d'un relai par AVK pour une TVP/EP non grave, quelles sont les modalités de ce relai et les critères d'arrêt de l'héparine ?","a":"<p>Le relai avec les AVK (exemple : <strong>warfarine</strong>) est initié <strong>dès J1</strong>. L'héparine de bas poids moléculaire (HBPM) ou le fondaparinux peuvent être arrêtés après <strong>au moins 5 jours de chevauchement</strong> avec l'AVK, et lorsque l'<strong>INR est dans la cible thérapeutique (2-3)</strong> sur <strong>deux prélèvements consécutifs</strong>.</p>"},{"i":"dbce8942a2ba","n":226,"o":"226-10","u":"Prise en charge","t":"Connaître les principes de traitement d’une TVP/EP non grave à la phase initiale (voir item 330)","q":"Quelles sont les contre-indications majeures à l'instauration d'un traitement anticoagulant pour une TVP/EP ?","a":"<p>Les contre-indications majeures sont :</p><ul><li>Une <strong>coagulopathie sévère</strong> (thrombopénie &lt; 30 G/L, hémophilie, TP &lt; 30 %).</li><li>Une <strong>hémorragie intracrânienne sévère</strong>.</li><li>Une <strong>hémorragie active non contrôlable</strong>.</li></ul>"},{"i":"e43a221a810b","n":226,"o":"226-10","u":"Prise en charge","t":"Connaître les principes de traitement d’une TVP/EP non grave à la phase initiale (voir item 330)","q":"Quelles sont les mesures associées au traitement anticoagulant d'une TVP/EP non grave ?","a":"<p>Les mesures associées sont :</p><ul><li>La <strong>compression élastique</strong>, à instaurer dès le diagnostic de TVP.</li><li>Le <strong>lever précoce</strong>, 1 heure après l'initiation de l'anticoagulation (sauf en cas de choc ou d'hypoxie, où l'alitement est de rigueur).</li><li>La <strong>remise d'une carte d'anticoagulé</strong> au patient.</li></ul>"},{"i":"13208797f9e3","n":226,"o":"226-11","u":"Prise en charge","t":"Connaître les indications et contre-indications de la compression élastique (TVP des membres inférieurs)","q":"Quelle est l'indication principale de la compression élastique dans le contexte d'une TVP des membres inférieurs ?","a":"<p>La compression élastique est indiquée pour <strong>toute TVP des membres inférieurs</strong> (isolée ou associée à une EP), dès la phase initiale. Son objectif principal est de <strong>prévenir le syndrome post-thrombotique</strong>.</p>"},{"i":"55533ddf2a83","n":226,"o":"226-11","u":"Prise en charge","t":"Connaître les indications et contre-indications de la compression élastique (TVP des membres inférieurs)","q":"Quelles sont les modalités pratiques de la compression élastique pour une TVP des membres inférieurs ?","a":"<p>Les modalités sont :</p><ul><li>Une compression de <strong>classe 3</strong>, soit <strong>30-40 mmHg</strong>.</li><li>Elle peut être sous forme de <strong>chaussettes ou de bas</strong>.</li><li>La durée minimale est de <strong>≥ 6 mois</strong> (et <strong>≥ 2 ans</strong> selon le Collège de Cardiologie en cas de TVP proximale).</li></ul>"},{"i":"7508afa5336c","n":226,"o":"226-11","u":"Prise en charge","t":"Connaître les indications et contre-indications de la compression élastique (TVP des membres inférieurs)","q":"Quelles sont les contre-indications spécifiques à la compression élastique dans la prise en charge d'une TVP des membres inférieurs ?","a":"<p>Il existe quatre contre-indications principales :</p><ul><li>Un <strong>IPS &lt; 0,6</strong> (en cas d'artériopathie).</li><li>Une <strong>microangiopathie diabétique</strong> avec une TcPO₂ &lt; 30 mmHg.</li><li>La <strong>phlébite bleue</strong> (phlegmatia caerulea).</li><li>La <strong>thrombose septique</strong>.</li></ul>"},{"i":"52a4200b66e4","n":226,"o":"226-12","u":"Prise en charge","t":"Connaître les contraceptions contre-indiquées en cas de MTEV (TVP, EP)","q":"Quelle est la conduite à tenir en cas de MTEV survenant chez une patiente sous contraception œstro-progestative (COP) ?","a":"<p>En cas de MTEV survenant sous COP, il faut :</p><ul><li>Arrêter la COP, idéalement à la fin de la plaquette en cours, sans urgence immédiate.</li><li>Relayer par une <strong>contraception non thrombogène</strong>, proposée par le gynécologue.</li><li>S'assurer d'une contraception efficace durant le traitement anticoagulant en raison du risque tératogène des <strong>AVK</strong> et des <strong>AOD</strong>.</li></ul>"},{"i":"7215d7297a47","n":226,"o":"226-12","u":"Prise en charge","t":"Connaître les contraceptions contre-indiquées en cas de MTEV (TVP, EP)","q":"Quelles sont les alternatives contraceptives non thrombogènes qui peuvent être proposées chez une patiente avec un risque ou un antécédent de MTEV ?","a":"<p>Les alternatives contraceptives non thrombogènes qui peuvent être proposées sont :</p><ul><li>Le <strong>micro-progestatif oral</strong>.</li><li>L'<strong>implant à la progestérone</strong>.</li><li>Le <strong>stérilet (DIU) à la progestérone</strong>.</li><li>Le <strong>stérilet (DIU) au cuivre</strong>.</li></ul>"},{"i":"c208bc3c9f90","n":226,"o":"226-12","u":"Prise en charge","t":"Connaître les contraceptions contre-indiquées en cas de MTEV (TVP, EP)","q":"Quelles sont les situations où une contraception œstro-progestative (COP) est contre-indiquée chez une patiente ayant un antécédent ou un risque de maladie thrombo-embolique veineuse (MTEV) ?","a":"<p>Une contraception œstro-progestative (COP) est contre-indiquée dans les situations suivantes :</p><ul><li><strong>Antécédent personnel de MTEV</strong> (Thrombose Veineuse Profonde ou Embolie Pulmonaire).</li><li>Présence d'une <strong>thrombophilie génétique ou acquise</strong>.</li><li><strong>Apparenté du 1<sup>er</sup> degré</strong> ayant eu une MTEV idiopathique avant l'âge de <strong>45 ans</strong>.</li></ul>"},{"i":"0833c4083960","n":226,"o":"226-13","u":"Prise en charge","t":"Connaître les situations nécessitant une prévention de la MTEV","q":"Quelles sont les recommandations de prévention de la MTEV lors d'un voyage prolongé (> 6 heures) ?","a":"<p>Les conseils simples incluent l'<strong>hydratation</strong>, la <strong>contraction régulière des mollets</strong> et le port de <strong>vêtements non serrés</strong>. Si des facteurs de risque sont associés, une <strong>compression de classe 2-3</strong> et/ou une <strong>HBPM préventive avant le départ</strong> peuvent être envisagées.</p>"},{"i":"20d6d7c98970","n":226,"o":"226-13","u":"Prise en charge","t":"Connaître les situations nécessitant une prévention de la MTEV","q":"Quelles sont les indications de l'anticoagulation préventive de la MTEV chez les patients hospitalisés en milieu médical ?","a":"<p>Une anticoagulation préventive (par HBPM ou fondaparinux) est indiquée chez les patients <strong>âgés de plus de 40 ans</strong>, <strong>hospitalisés plus de 3 jours</strong>, en cas de :</p><ul><li>Infarctus du Myocarde (IDM)</li><li>Accident Vasculaire Cérébral (AVC) ischémique</li><li>Insuffisance cardiaque ou respiratoire aiguë</li><li>Affection rhumatologique, MICI ou infection associée à un facteur de risque.</li></ul><p>La durée du traitement préventif est de <strong>7 à 14 jours</strong>.</p>"},{"i":"7b36d568eb9c","n":226,"o":"226-13","u":"Prise en charge","t":"Connaître les situations nécessitant une prévention de la MTEV","q":"Quelles sont les mesures non médicamenteuses de prévention de la maladie thrombo-embolique veineuse (MTEV) ?","a":"<p>Les mesures non médicamenteuses de prévention de la MTEV reposent sur la <strong>mobilisation précoce</strong> et la <strong>compression mécanique</strong> (bas de contention).</p>"},{"i":"e2ba60c08276","n":226,"o":"226-13","u":"Prise en charge","t":"Connaître les situations nécessitant une prévention de la MTEV","q":"Quelles sont les indications de l'anticoagulation préventive de la MTEV dans le contexte post-opératoire ?","a":"<ul><li><strong>Risque faible</strong> (chirurgie mineure, < 40 ans, sans FDR) : <strong>pas d'anticoagulation</strong>.</li><li><strong>Risque modéré</strong> (chirurgie générale, > 40 ans) : <strong>HBPM préventive</strong>.</li><li><strong>Risque élevé</strong> (chirurgie de la hanche/genou, chirurgie carcinologique, ATCD de MTEV) : <strong>HBPM préventive</strong>, prolongée jusqu'à <strong>5 semaines en chirurgie de hanche</strong>.</li></ul>"},{"i":"2e2ec98d9a3e","n":226,"o":"226-2","u":"Étiologies","t":"Connaître les situations qui favorisent la maladie thromboembolique veineuse (MTEV) : circonstances de survenue, facteurs favorisants temporaires et persistants","q":"Quels sont les facteurs favorisants persistants majeurs de la maladie thromboembolique veineuse (MTEV) ?","a":"Les facteurs favorisants persistants majeurs de la MTEV sont :\n<ul>\n<li><strong>Cancer actif</strong>.</li>\n<li><strong>Thrombophilie majeure</strong>, notamment le <strong>déficit en antithrombine</strong> et le <strong>Syndrome des Anticorps Anti-Phospholipides (SAPL)</strong>, qui est la seule thrombophilie acquise.</li>\n</ul>"},{"i":"564f3cf148bc","n":226,"o":"226-2","u":"Étiologies","t":"Connaître les situations qui favorisent la maladie thromboembolique veineuse (MTEV) : circonstances de survenue, facteurs favorisants temporaires et persistants","q":"Quels sont les pièges à éviter concernant les facteurs de risque de la maladie thromboembolique veineuse (MTEV) ?","a":"Il est important de retenir que :\n<ul>\n<li>Le <strong>tabac</strong> et la <strong>dyslipidémie</strong> ne sont <strong>pas des facteurs de risque de MTEV</strong> (à la différence du risque artériel).</li>\n<li>Dans environ <strong>50 % des cas</strong>, aucun facteur favorisant n'est identifié.</li>\n<li>Un <strong>antécédent familial de MTEV</strong>, même en l'absence de thrombophilie héréditaire détectée, doit être considéré comme un marqueur de thrombophilie héréditaire.</li>\n</ul>"},{"i":"7972cfd5ccb6","n":226,"o":"226-2","u":"Étiologies","t":"Connaître les situations qui favorisent la maladie thromboembolique veineuse (MTEV) : circonstances de survenue, facteurs favorisants temporaires et persistants","q":"Quels sont les facteurs favorisants persistants mineurs de la maladie thromboembolique veineuse (MTEV) ?","a":"Les facteurs favorisants persistants mineurs de la MTEV comprennent :\n<ul>\n<li><strong>Âge supérieur à 65 ans</strong>.</li>\n<li><strong>Obésité</strong>.</li>\n<li><strong>Syndrome néphrotique</strong>.</li>\n<li><strong>Hémoglobinurie Paroxystique Nocturne (HPN)</strong>.</li>\n<li><strong>Maladies Inflammatoires Chroniques Intestinales (MICI)</strong>.</li>\n<li><strong>Maladies inflammatoires chroniques articulaires</strong>.</li>\n<li><strong>Thrombophilie non majeure</strong>, telle que le <strong>déficit en protéine C ou protéine S</strong>, la <strong>mutation Leiden du facteur V</strong>, ou la <strong>mutation G20210A de la prothrombine</strong>.</li>\n</ul>"},{"i":"cd7972587f1e","n":226,"o":"226-2","u":"Étiologies","t":"Connaître les situations qui favorisent la maladie thromboembolique veineuse (MTEV) : circonstances de survenue, facteurs favorisants temporaires et persistants","q":"Quels sont les facteurs favorisants temporaires majeurs de la maladie thromboembolique veineuse (MTEV) ?","a":"Les facteurs favorisants temporaires majeurs de la MTEV incluent :\n<ul>\n<li><strong>Chirurgie sous anesthésie générale</strong> de moins de 3 mois.</li>\n<li><strong>Fracture d'un membre inférieur</strong> de moins de 3 mois.</li>\n<li><strong>Immobilisation</strong> de plus de 3 jours pour motif médical aigu de moins de 3 mois.</li>\n<li>Prise de <strong>Contraceptifs Oraux (COP)</strong>, grossesse, post-partum, ou Traitement Hormonal de la Ménopause (THM) de moins de 3 mois.</li>\n</ul>"},{"i":"fe37a44d01f5","n":226,"o":"226-2","u":"Étiologies","t":"Connaître les situations qui favorisent la maladie thromboembolique veineuse (MTEV) : circonstances de survenue, facteurs favorisants temporaires et persistants","q":"Quels sont les facteurs favorisants temporaires mineurs de la maladie thromboembolique veineuse (MTEV) ?","a":"Les facteurs favorisants temporaires mineurs de la MTEV sont :\n<ul>\n<li><strong>Traumatisme d'un membre inférieur non plâtré</strong> avec mobilité réduite pendant au moins 3 jours (survenu il y a moins de 2 mois).</li>\n<li><strong>Immobilisation</strong> de moins de 3 jours (survenue il y a moins de 3 mois).</li>\n<li><strong>Voyage</strong> de plus de 6 heures.</li>\n<li>Traitement par <strong>Érythropoïétine (EPO)</strong>.</li>\n<li>Présence d'une <strong>voie veineuse centrale</strong>.</li>\n</ul>"},{"i":"0d35f50202e3","n":226,"o":"226-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une MTEV (TVP, EP) : signes cliniques, stratégie diagnostique incluant les scores, signes paracliniques, principaux diagnostics différentiels","q":"Quelle est la stratégie diagnostique face à une suspicion de maladie thrombo-embolique veineuse (MTEV) ?","a":"<p>La stratégie diagnostique est la suivante :</p><ol><li>Évaluer la <strong>probabilité clinique</strong> à l'aide d'un score (Wells pour la TVP ; Wells ou Genève révisé pour l'EP).</li><li>Si la probabilité clinique n'est <strong>pas forte</strong>, doser les <strong>D-dimères</strong>. Si les D-dimères sont négatifs, le diagnostic est éliminé.</li><li>Si la probabilité clinique est <strong>forte</strong> ou si les <strong>D-dimères sont positifs</strong>, réaliser une <strong>imagerie d'emblée</strong> :<ul><li>Pour la TVP : <strong>échodoppler veineux</strong> des membres inférieurs.</li><li>Pour l'EP : <strong>angio-TDM pulmonaire</strong>.</li></ul></li></ol><p>Le diagnostic d'EP doit être établi en moins de <strong>24 heures</strong>.</p>"},{"i":"3218b1efd702","n":226,"o":"226-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une MTEV (TVP, EP) : signes cliniques, stratégie diagnostique incluant les scores, signes paracliniques, principaux diagnostics différentiels","q":"Quels sont les signes cliniques orientant vers une embolie pulmonaire (EP) ?","a":"<p>Les signes cliniques orientant vers une EP sont les suivants :</p><ul><li><strong>Dyspnée brutale</strong></li><li><strong>Douleur thoracique pleurale</strong></li><li><strong>Hémoptysie</strong></li><li><strong>Syncope</strong></li><li><strong>Tachypnée constante</strong></li><li>Signes d'<strong>insuffisance cardiaque droite aiguë</strong> (turgescence jugulaire, reflux hépato-jugulaire)</li><li>Une EP à haut risque est associée à un <strong>état de choc</strong>.</li><li>À retenir : une dyspnée brutale avec une auscultation pulmonaire normale est une EP jusqu'à preuve du contraire.</li></ul>"},{"i":"71a759db9ddb","n":226,"o":"226-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une MTEV (TVP, EP) : signes cliniques, stratégie diagnostique incluant les scores, signes paracliniques, principaux diagnostics différentiels","q":"Comment évaluer la probabilité clinique d'une embolie pulmonaire (EP) ?","a":"<p>La probabilité clinique d'une EP est évaluée par les <strong>scores de Wells ou de Genève révisé</strong> pour l'EP.</p><ul><li><strong>Score de Wells pour l'EP</strong> : Un score ≥ 2 indique une EP probable, et un score de 0-1 une EP peu probable.</li><li><strong>Score de Genève révisé</strong> : Une interprétation en 2 niveaux donne une EP probable pour un score ≥ 3 et peu probable pour 0-2 points. (Une interprétation en 3 niveaux est également possible : Faible (0-1), Intermédiaire (2-4), Forte (≥ 5)).</li></ul>"},{"i":"ab763f2cad8a","n":226,"o":"226-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une MTEV (TVP, EP) : signes cliniques, stratégie diagnostique incluant les scores, signes paracliniques, principaux diagnostics différentiels","q":"Comment évaluer la probabilité clinique d'une thrombose veineuse profonde (TVP) ?","a":"<p>La probabilité clinique d'une TVP est évaluée par le <strong>score de Wells</strong> pour la TVP. Un score ≥ 2 indique une probabilité forte (probable), tandis qu'un score < 2 indique une probabilité faible (improbable).</p>"},{"i":"b7ea90ac36bb","n":226,"o":"226-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une MTEV (TVP, EP) : signes cliniques, stratégie diagnostique incluant les scores, signes paracliniques, principaux diagnostics différentiels","q":"Quels sont les signes paracliniques d'orientation pouvant être observés à l'ECG et à la radiographie thoracique (RXT) en cas d'embolie pulmonaire (EP) ?","a":"<p>Les signes paracliniques d'orientation dans l'EP sont ni sensibles ni spécifiques :</p><ul><li><strong>ECG</strong> (mémo BASTON) : <ul><li><strong>B</strong>loc de branche droit</li><li><strong>A</strong>xe dévié à droite</li><li><strong>S1Q3</strong> (onde S en D1, onde Q en D3)</li><li><strong>T</strong>achycardie sinusale (le plus fréquent)</li><li><strong>O</strong>ndes T négatives de V1 à V4</li><li><strong>N</strong>ormal possible</li></ul></li><li><strong>Radiographie thoracique</strong> (RXT, mémo ABCDEF) : <ul><li><strong>A</strong>scension d'une coupole</li><li><strong>B</strong>ande d'atélectasie</li><li><strong>C</strong>larté d'un champ pulmonaire</li><li><strong>D</strong>ilatation des cavités droites</li><li><strong>É</strong>panchement pleural</li><li>In<strong>f</strong>arctus pulmonaire</li><li>La RXT est souvent <strong>normale</strong>.</li></ul></li><li>Une gazométrie peut montrer une <strong>hypoxémie</strong> associée à une <strong>hypocapnie</strong> (PaO₂ + PaCO₂ &lt; 120 mmHg), mais elle peut aussi être normale.</li></ul>"},{"i":"f93e6718814c","n":226,"o":"226-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une MTEV (TVP, EP) : signes cliniques, stratégie diagnostique incluant les scores, signes paracliniques, principaux diagnostics différentiels","q":"Quels sont les signes cliniques orientant vers une thrombose veineuse profonde (TVP) ?","a":"<p>Les signes cliniques orientant vers une TVP sont les suivants :</p><ul><li><strong>Douleur du mollet</strong> (observée dans environ 60% des cas)</li><li><strong>Œdème unilatéral</strong> prenant le godet, avec une différence de circonférence > 3 cm par rapport au côté controlatéral</li><li><strong>Signe de Homans</strong> (douleur du mollet à la dorsiflexion forcée du pied)</li><li>Diminution du <strong>ballottement du mollet</strong></li><li>Signes inflammatoires locaux (chaleur, rougeur)</li><li>Survenue brutale et unilatérale des symptômes</li><li>Une forme grave, la <strong>phlegmatia alba dolens</strong>, se caractérise par une douleur violente, une impotence fonctionnelle absolue, une fièvre, une jambe livide et un œdème dur ne prenant pas le godet.</li></ul>"},{"i":"64c346602108","n":226,"o":"226-5","u":"Identifier une urgence","t":"Savoir identifier et connaître la démarche diagnostique en cas d’EP à haut risque","q":"Comment le diagnostic d'embolie pulmonaire (EP) à haut risque est-il confirmé après l'évaluation initiale chez un patient stabilisé ?","a":"<p>Le diagnostic d'EP à haut risque est confirmé par un <strong>angio-TDM thoracique</strong> (tomodensitométrie avec injection de produit de contraste), réalisé <strong>dès que le patient est transportable ou stabilisé</strong>.</p>"},{"i":"87fbb87cadec","n":226,"o":"226-5","u":"Identifier une urgence","t":"Savoir identifier et connaître la démarche diagnostique en cas d’EP à haut risque","q":"Quels sont les éléments recherchés lors d'une échographie cardiaque trans-thoracique (ETT) pour diagnostiquer une embolie pulmonaire (EP) à haut risque ?","a":"<p>L'ETT recherche des <strong>signes indirects</strong> d'EP grave, suffisant pour orienter le diagnostic et débuter le traitement. Il s'agit de :</p><ul><li>Une <strong>dilatation du ventricule droit (VD)</strong>.</li><li>Une <strong>dysfonction du ventricule droit (VD)</strong>.</li></ul><p>L'absence de signes de surcharge des cavités droites à l'ETT rend le diagnostic d'EP grave peu probable et doit faire rechercher une autre cause de choc.</p>"},{"i":"cee09dd582d3","n":226,"o":"226-5","u":"Identifier une urgence","t":"Savoir identifier et connaître la démarche diagnostique en cas d’EP à haut risque","q":"Comment définit-on une embolie pulmonaire (EP) à haut risque chez un patient ?","a":"<p>Une EP est classée à <strong>haut risque</strong> en présence d'un <strong>état de choc</strong>, défini par une Pression Artérielle Systolique (PAS) inférieure à <strong>90 mmHg</strong>, ou une chute de plus de 40 mmHg pendant au moins 15 minutes, et ce <strong>indépendamment des autres paramètres</strong>.</p>"},{"i":"f935c2e35e4b","n":226,"o":"226-5","u":"Identifier une urgence","t":"Savoir identifier et connaître la démarche diagnostique en cas d’EP à haut risque","q":"Quelle est la démarche diagnostique initiale en cas de suspicion d'embolie pulmonaire (EP) à haut risque chez un patient instable hémodynamiquement ?","a":"<p>Devant une suspicion d'EP chez un patient en choc, la démarche diagnostique initiale est une <strong>échographie cardiaque trans-thoracique (ETT)</strong>, réalisée <strong>au lit du patient</strong>. Il s'agit d'une urgence vitale et le patient instable ne doit pas être déplacé pour un scanner.</p>"},{"i":"57d467073e34","n":226,"o":"226-6","u":"Diagnostic positif","t":"Connaître les indications de dosage des D-dimères (TVP, EP) et la notion de seuil d’ajustement à l’âge dans l’EP","q":"Dans quelles situations cliniques le dosage des D-dimères n'est-il PAS indiqué ou n'est-il PAS interprétable pour le diagnostic de MTEV ?","a":"<ul><li>Le dosage n'est <strong>pas indiqué</strong> si la <strong>probabilité clinique est forte</strong> (il faut réaliser une imagerie d'emblée).</li><li>Il n'est <strong>pas indiqué</strong> dans les situations de <strong>faux positifs</strong>, car leur VPP est faible : <strong>cancer, grossesse, inflammation, post-opératoire, âge > 80 ans, CIVD</strong>.</li><li>Le dosage est <strong>non interprétable sous anticoagulant curatif</strong>.</li></ul>"},{"i":"c10d364a7369","n":226,"o":"226-6","u":"Diagnostic positif","t":"Connaître les indications de dosage des D-dimères (TVP, EP) et la notion de seuil d’ajustement à l’âge dans l’EP","q":"Quel est le seuil de négativité des D-dimères pour un patient de moins de 50 ans et un patient de 70 ans dans le cadre du diagnostic d'une embolie pulmonaire (EP) ?","a":"<ul><li>Pour un patient <strong>âgé de moins de 50 ans</strong>, le dosage de D-dimères est considéré comme négatif si la concentration est <strong>inférieure à 500 ng/mL</strong>.</li><li>Pour un patient <strong>âgé de 70 ans</strong>, le seuil ajusté à l'âge est <strong >âge × 10</strong>, soit <strong>700 ng/mL</strong>.</li></ul>"},{"i":"dba75423917a","n":226,"o":"226-6","u":"Diagnostic positif","t":"Connaître les indications de dosage des D-dimères (TVP, EP) et la notion de seuil d’ajustement à l’âge dans l’EP","q":"Quelle est l'utilité clinique du dosage des D-dimères dans le diagnostic de la maladie thromboembolique veineuse (MTEV) ?","a":"<p>Le dosage des D-dimères permet d'<strong>éliminer une thrombose veineuse profonde (TVP) ou une embolie pulmonaire (EP)</strong> lorsque la probabilité clinique est <strong>non forte</strong>. Leur excellente <strong>VPN (95%)</strong> et leur bonne sensibilité en font un outil d'exclusion efficace.</p>"},{"i":"02761f612722","n":226,"o":"226-7","u":"Examens complémentaires","t":"Connaître la place et les limites de l’échodoppler veineux (TVP, EP)","q":"Quelles sont les principales limites de l'échodoppler veineux dans le diagnostic de la thrombose veineuse profonde (TVP) ?","a":"<p>Les principales limites de l'échodoppler veineux sont :</p><ul><li>Il est <strong>très spécifique en proximal</strong> mais <strong>moins spécifique en distal</strong>.</li><li>Il nécessite un <strong>appareillage de haute résolution</strong> et une <strong>sonde adaptée</strong>.</li><li>Il dépend fortement de l'<strong>opérateur</strong>, qui doit être <strong>expérimenté</strong>, et des <strong>conditions techniques optimales</strong>.</li></ul>"},{"i":"4a9ed1d2e1bb","n":226,"o":"226-7","u":"Examens complémentaires","t":"Connaître la place et les limites de l’échodoppler veineux (TVP, EP)","q":"Quelle est la place de l'échodoppler veineux des membres inférieurs dans le diagnostic de la thrombose veineuse profonde (TVP) ?","a":"<p>L'échodoppler veineux des membres inférieurs est l'examen de <strong>1<sup>re</sup> intention</strong> pour confirmer une TVP. Il présente de <strong>bonnes sensibilité et spécificité</strong> (&gt; 95 %), est <strong>non invasif</strong> et <strong>non irradiant</strong>.</p>"},{"i":"7510ddb8f3ac","n":226,"o":"226-7","u":"Examens complémentaires","t":"Connaître la place et les limites de l’échodoppler veineux (TVP, EP)","q":"Quelle est l'interprétation d'un échodoppler veineux des membres inférieurs dans le contexte d'une suspicion d'embolie pulmonaire (EP) ?","a":"<p>Dans le contexte d'une suspicion d'EP :</p><ul><li>La découverte d'une <strong>TVP proximale</strong> à l'échodoppler <strong>confirme le diagnostic</strong> d'EP sans autre examen.</li><li>Un échodoppler veineux <strong>normal n'exclut pas une EP</strong>.</li></ul>"},{"i":"e53fcd5dbfbe","n":226,"o":"226-7","u":"Examens complémentaires","t":"Connaître la place et les limites de l’échodoppler veineux (TVP, EP)","q":"Quels sont les signes échographiques clés d'une thrombose veineuse profonde (TVP) à l'échodoppler veineux ?","a":"<p>Les signes échographiques clés d'une TVP sont :</p><ul><li>L'<strong>absence de compressibilité</strong> de la veine par la sonde (signe clé, recherché sur les axes fémoraux et poplités).</li><li>La visualisation d'un <strong>caillot endoluminal</strong> (image de caillot veineux, très spécifique).</li><li>Un <strong>remplissage partiel ou une absence de flux</strong> au Doppler couleur dans le segment thrombosé.</li></ul>"},{"i":"5c29b4a08fdd","n":226,"o":"226-8","u":"Examens complémentaires","t":"Connaître la place et les limites des examens d’imagerie dans l’EP : angiotomodensitométrie thoracique, scintigraphie de ventilation-perfusion, échographie cardiaque trans-thoracique","q":"Quelles sont les limites de l'échographie cardiaque trans-thoracique (ETT) pour visualiser directement l'embolie pulmonaire ?","a":"<p>Les limites de l'ETT sont que le thrombus est <strong>rarement visualisé</strong> sur cet examen (il est mieux visualisé en ETO - échographie trans-œsophagienne). De plus, l'<strong>absence de surcharge droite</strong> à l'ETT rend l'embolie pulmonaire peu probable.</p>"},{"i":"7d0f9ac3ea1e","n":226,"o":"226-8","u":"Examens complémentaires","t":"Connaître la place et les limites des examens d’imagerie dans l’EP : angiotomodensitométrie thoracique, scintigraphie de ventilation-perfusion, échographie cardiaque trans-thoracique","q":"Quelle est la principale limite de la scintigraphie de ventilation-perfusion dans le diagnostic de l'embolie pulmonaire ?","a":"<p>La scintigraphie de ventilation-perfusion est <strong>peu interprétable</strong> en cas de <strong>pathologie cardiorespiratoire préexistante</strong>, car celle-ci peut perturber la ventilation et masquer un défect attribuable à l'EP.</p>"},{"i":"a6288d5e4fdf","n":226,"o":"226-8","u":"Examens complémentaires","t":"Connaître la place et les limites des examens d’imagerie dans l’EP : angiotomodensitométrie thoracique, scintigraphie de ventilation-perfusion, échographie cardiaque trans-thoracique","q":"Quelles sont les principales limites de l'angio-TDM thoracique pour le diagnostic de l'embolie pulmonaire ?","a":"<p>Les principales limites de l'angio-TDM thoracique sont :</p><ul><li>L'<strong>allergie aux produits de contraste iodés</strong>.</li><li>L'<strong>insuffisance rénale sévère</strong>.</li><li>Si l'examen est négatif mais que la probabilité clinique est forte, il faut <strong>poursuivre les explorations</strong>.</li></ul>"},{"i":"c2e4d85ab907","n":226,"o":"226-8","u":"Examens complémentaires","t":"Connaître la place et les limites des examens d’imagerie dans l’EP : angiotomodensitométrie thoracique, scintigraphie de ventilation-perfusion, échographie cardiaque trans-thoracique","q":"Quand la scintigraphie de ventilation-perfusion est-elle indiquée dans le diagnostic de l'embolie pulmonaire et comment est-elle interprétée selon la classification PIOPED ?","a":"<p>La scintigraphie de ventilation-perfusion est indiquée en cas de <strong>contre-indication</strong> ou de difficulté d'accès à l'angio-TDM, ou en cas de <strong>forte suspicion clinique</strong> avec un angio-TDM négatif.</p><p>Selon la classification <strong>PIOPED</strong> :</p><ul><li>Un examen <strong>normal exclut l'EP</strong> (sensibilité de 100%).</li><li>Un « <strong>mismatch</strong> » (haute probabilité) correspond à <strong>au moins 2 défects segmentaires de perfusion sans défect ventilatoire</strong> en regard.</li></ul>"},{"i":"c9d843896ffb","n":226,"o":"226-8","u":"Examens complémentaires","t":"Connaître la place et les limites des examens d’imagerie dans l’EP : angiotomodensitométrie thoracique, scintigraphie de ventilation-perfusion, échographie cardiaque trans-thoracique","q":"Quel est le rôle de l'échographie cardiaque trans-thoracique (ETT) dans le diagnostic et la prise en charge de l'embolie pulmonaire (EP) ?","a":"<p>L'ETT confirme une <strong>EP grave</strong> si l'angio-TDM n'est pas disponible, surtout en cas de forte probabilité clinique. Elle peut montrer des <strong>signes directs</strong> comme un <strong>thrombus</strong> dans les cavités droites, ou des <strong>signes indirects</strong> de retentissement, tels que :</p><ul><li>Une <strong>dilatation du ventricule droit (VD)</strong>.</li><li>Une <strong>hypokinésie du VD</strong>.</li><li>Un <strong>septum paradoxal</strong>.</li><li>Une <strong>élévation des pressions artérielles pulmonaires (PAPs)</strong>.</ul><p>L'ETT est également utile pour <strong>stratifier le risque</strong> de l'EP (EP à risque intermédiaire).</p>"},{"i":"d32190746790","n":226,"o":"226-8","u":"Examens complémentaires","t":"Connaître la place et les limites des examens d’imagerie dans l’EP : angiotomodensitométrie thoracique, scintigraphie de ventilation-perfusion, échographie cardiaque trans-thoracique","q":"Quelle est la place de l'angio-TDM thoracique dans le diagnostic de l'embolie pulmonaire (EP) et quels sont ses critères de positivité ?","a":"<p>L'angio-TDM thoracique est l'examen de <strong>première intention</strong> pour le diagnostic positif de l'EP. Ses critères de positivité sont :</p><ul><li>Une <strong>lacune endovasculaire</strong>.</li><li>Une <strong>absence d'opacification</strong> d'une artère segmentaire ou proximale.</li></ul><p>Un examen positif confirme l'EP, quelle que soit la probabilité clinique.</p>"},{"i":"10931fe6b6f5","n":226,"o":"226-9","u":"Prise en charge","t":"Connaître les signes de gravité d’une EP et savoir reconnaître les patients pouvant être pris en charge en ambulatoire en cas d’EP","q":"Quels sont les six critères du score sPESI pour évaluer la gravité d'une embolie pulmonaire ?","a":"<p>Le score sPESI attribue <strong>1 point</strong> pour chacun des critères suivants :</p><ul><li>Âge <strong>> 80 ans</strong>.</li><li>Saturation en oxygène (SatO₂) <strong>< 90 %</strong>.</li><li>Pression Artérielle Systolique (PAS) <strong>< 100 mmHg</strong>.</li><li>Fréquence Cardiaque (FC) <strong>> 110/min</strong>.</li><li>Présence d'un <strong>cancer</strong>.</li><li>Présence d'une <strong>insuffisance cardiaque ou respiratoire chronique</strong>.</li></ul>"},{"i":"295fe9fa2b05","n":226,"o":"226-9","u":"Prise en charge","t":"Connaître les signes de gravité d’une EP et savoir reconnaître les patients pouvant être pris en charge en ambulatoire en cas d’EP","q":"Quels sont les trois plans d'évaluation de la gravité d'une embolie pulmonaire ?","a":"<p>La gravité d'une embolie pulmonaire s'évalue sur :</p><ul><li>Le plan <strong>hémodynamique</strong>.</li><li>Un <strong>score clinique pronostique</strong> (score sPESI).</li><li>Des <strong>marqueurs de souffrance du ventricule droit (VD)</strong>.</li></ul>"},{"i":"2e4af7d0a842","n":226,"o":"226-9","u":"Prise en charge","t":"Connaître les signes de gravité d’une EP et savoir reconnaître les patients pouvant être pris en charge en ambulatoire en cas d’EP","q":"Quels sont les signes de souffrance du ventricule droit (VD) à rechercher pour évaluer la gravité d'une embolie pulmonaire ?","a":"<p>Les signes de souffrance du ventricule droit (VD) sont :</p><ul><li>Une <strong>dysfonction du VD à l'échographie transthoracique (ETT) ou à la tomodensitométrie</strong>, avec un rapport VD/VG (ventricule droit/ventricule gauche) <strong>> 0,9</strong> ou une <strong>hypokinésie</strong>.</li><li>Une <strong>élévation des biomarqueurs</strong> : <strong>troponine I ou T</strong>, et/ou <strong>BNP / NT-proBNP</strong>.</li></ul>"},{"i":"31270044e512","n":226,"o":"226-9","u":"Prise en charge","t":"Connaître les signes de gravité d’une EP et savoir reconnaître les patients pouvant être pris en charge en ambulatoire en cas d’EP","q":"Quels sont les critères permettant d'envisager une prise en charge ambulatoire pour une embolie pulmonaire ?","a":"<p>Une prise en charge ambulatoire d'une embolie pulmonaire est possible si :</p><ul><li>Le score <strong>sPESI est de 0</strong>.</li><li>Il y a une <strong>absence de dysfonction du ventricule droit</strong> (VD).</li><li>Il y a une <strong>absence de signe de gravité hémodynamique</strong>.</li><li>Le <strong>terrain et le contexte social sont favorables</strong>.</li><li>Le <strong>risque hémorragique est faible</strong>.</li></ul>"},{"i":"50026952839e","n":226,"o":"226-9","u":"Prise en charge","t":"Connaître les signes de gravité d’une EP et savoir reconnaître les patients pouvant être pris en charge en ambulatoire en cas d’EP","q":"Comment définit-on la gravité hémodynamique d'une embolie pulmonaire dite « à haut risque » ?","a":"<p>Une embolie pulmonaire est dite « à haut risque » en présence d'un <strong>état de choc</strong>, défini par une Pression Artérielle Systolique (PAS) inférieure à <strong>90 mmHg</strong> ou une chute de la PAS supérieure à <strong>40 mmHg</strong>, persistant pendant au moins <strong>15 minutes</strong>.</p>"},{"i":"ad67be39f6f4","n":226,"o":"226-9","u":"Prise en charge","t":"Connaître les signes de gravité d’une EP et savoir reconnaître les patients pouvant être pris en charge en ambulatoire en cas d’EP","q":"Dans quels cas une embolie pulmonaire impose-t-elle impérativement une hospitalisation ?","a":"<p>Toute embolie pulmonaire à <strong>haut risque</strong> (instabilité hémodynamique) ou présentant une <strong>dysfonction du ventricule droit</strong> (VD) doit impérativement être hospitalisée.</p>"}]};